programs.sol:
"""Lexical responses to header inclusion, a Program class, and Chinese 就.

C/C++ inclusion directives are positive, but weaker at document start and
later in a list of headers.  Program after `class` is positive too.
Chinese 就 is negative, especially in 并就 ('and concerning') and 是就
('is with respect to'). Repeated centered-dot separators are positive.
Dictionary glosses also identify Chinese words about clarity, firmness,
connection and focus (negative), or proceeding in advance (positive).
This is a coarse lexical approximation, not a complete semantic analysis.
"""

from functools import lru_cache
import re
import regex
import cedict

READS = ()


@lru_cache(maxsize=8192)
def chinese_response(word):
    """Approximate a few lexical families using their main dictionary sense."""
    if len(word) < 2 or not regex.fullmatch(r"\p{Script=Han}+", word):
        return 0.0
    if word.endswith("的"):
        word = word[:-1]
    glosses = cedict.glosses(word)
    scale = 1.0
    if not glosses and len(word) > 2:
        modifier = " ".join(cedict.glosses(word[:-2])).lower()
        if re.search(r"\b(tightly|firmly|closely)\b", modifier):
            glosses = cedict.glosses(word[-2:])
            scale = 2.0
    senses = [g.lower() for g in glosses
              if not g.lower().startswith(("variant", "cl:", "surname"))]
    if not senses:
        return 0.0
    main = senses[0]
    if main.startswith(("firm", "staunch", "resolute", "steadfast",
                        "to fortify")):
        value = -0.9
    elif main.startswith(("clear", "to clarify", "to be certain", "to affirm")):
        value = -0.6
    elif main.startswith(("to combine", "to link", "to integrate")):
        value = -0.4
    elif main == "connection" and "to integrate" in senses:
        value = -0.6
    elif main.startswith(("prominent", "to revolve around")):
        value = -0.7
    elif main.startswith("to target"):
        value = -0.3
    elif "to precede" in main or "proceed in advance" in main:
        value = 1.15
    else:
        value = 0.0
    return scale * value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = prefix.token_strings[-1].strip()
    first = carry is None or carry[0] != doc
    if first:
        count, starts_include, previous = 0, word == '#include', ''
    else:
        _, count, starts_include, previous = carry

    value = chinese_response(word)
    if word == '#include':
        if first:
            value = 0.442
        else:
            value = 2.1 + 0.55 / (1.0 + count)
            if starts_include:
                value -= 0.2
        count += 1
    elif word == 'include' and previous.endswith('#'):
        value = 3.2
        count += 1
    elif word == 'Program' and previous == 'class':
        value = 2.7
    elif word == '就':
        if first:
            value = -1.0
        elif previous.endswith(('并', '並')):
            value = -5.9
        elif previous == '是':
            value = -2.1
        elif previous.endswith('造'):
            value = 0.25
        else:
            value = -0.3
    elif word == '··' and previous == word:
        value = 0.97

    return (doc, count, starts_include, word), value

"""Detect the first few digits of a symbol-prefixed number.

Money and # labels are strongest; addition signs, HTML character references,
and shell redirection are weaker. Parenthesized signs strengthen the response.
A larger leading digit weakens the response on the following digit. TeX-heavy
passages suppress the currency interpretation of an unescaped dollar sign.
Small extra rules cover display-style names and dollar/percent identifiers.
"""
import math
import re
import unicodedata

READS = ()
TEX = re.compile(
    r'\\(?:frac|sqrt|sum|cdot|times|pm|math\w+|left|right)\b'
    r'|\$[A-Za-z](?:\$|[_^=])'
)


def number_marker(s):
    if not s:
        return 0.0
    if s.endswith('&#'):
        return 2.2 if s[:1].isspace() else 1.6
    if s.endswith(('$$', '##', '++')):
        return 0.0
    if unicodedata.category(s[-1]) == 'Sc':
        value = 4.4 if s[-1] == '$' else 4.7
    elif s.endswith('#'):
        value = 5.2 if s[:1].isspace() else 4.4
    elif s.endswith(('+', '＋')):
        value = 1.0 if s[:1].isspace() else 0.3
    elif s.endswith('>&'):
        return 1.55
    elif s.endswith('%'):
        return 1.0
    else:
        return 0.0
    return value + (2.0 if '(' in s else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, strength, digits, lead = '', '', 0.0, 0, 1
        tail, math_age = '', 1000
    else:
        _, previous, before, strength, digits, lead, tail, math_age = carry
    s = prefix.token_strings[-1]
    tail = (tail + s)[-80:]
    math_age = 0 if TEX.search(tail) else math_age + 1
    value = 0.0
    if s.isascii() and s.isdigit():
        cue = number_marker(previous)
        if previous.endswith('$') and '\\' not in previous and math_age < 128:
            cue *= 0.03
        if cue:
            strength, digits, lead = cue, 1, max(1, int(s[0]))
        elif previous.isascii() and previous.isdigit() and strength:
            digits += 1
        else:
            strength, digits = 0.0, 0
        if digits == 1:
            value = strength
        elif digits == 2:
            value = strength * 0.65 / math.sqrt(lead)
            if before.endswith('&#'):
                value = -0.3
        elif digits == 3:
            value = strength * 0.04 / math.sqrt(lead)
    else:
        strength, digits = 0.0, 0
        if s == 'display' and previous.endswith('\\'):
            if '$' in previous or before.endswith('$'):
                value = 2.8
        elif s == 'style' and previous == 'display' and before.endswith('\\'):
            value = 1.8
        elif s.isalpha() and s.islower() and previous.endswith('$'):
            value = 0.2
        elif len(s) == 1 and s.isalpha() and previous.endswith('%'):
            value = 0.6
    return (doc, s, previous, strength, digits, lead, tail, math_age), float(value)

"""Sparse opening-format and East Asian quotation detector.

The main positive spike is a colon in document-initial 'Title:'. There are
also opening-date, '12', comment-header, and carriage-return-run spikes.
Closing East Asian title/quotation marks contribute negatively, except that
long, sentence-like quotations are weaker. Personal pronouns, capitalized
question words, and lowercase conjunctions have small opening-token biases.
Repeated middle dots give a small positive response; everything else is zero.
These rules leave most context-sensitive Chinese content words unexplained.
"""
import regex

READS = ()
PRONOUNS = frozenset("i you he she it we they me us them him her".split())
QUESTIONS = frozenset("who what which why how where when whose whom".split())
CONJUNCTIONS = frozenset("and or but nor yet".split())
CJK = regex.compile(r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count, previous, recent, only_returns = 0, '', '', True
    else:
        _, count, previous, recent, only_returns = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if count == 0 and token == 'Title':
        value = 0.89
    elif count == 1 and previous == 'Title' and token == ':':
        value = 8.08
    elif count == 1 and previous == 'Posted' and token == ' on':
        value = 3.96
    elif count == 1 and previous == '1' and token == '2':
        value = 2.60
    elif only_returns and token == '\r':
        value = 4.20
    elif count == 0 and token == '//\n':
        value = 4.85
    elif count == 0 and token.strip().lower() in PRONOUNS:
        value = 0.22
    elif count == 0 and token.strip().lower() in QUESTIONS and token.istitle():
        value = 0.45
    elif count == 0 and token.strip() in CONJUNCTIONS:
        value = -0.25
    elif token and set(token) == {'·'} and len(token) > 1:
        value = 0.46
    elif token.startswith('》'):
        value = -0.55
    elif token.startswith(('”', '」', '』', '】')) and CJK.search(recent):
        if token.startswith('”'):
            quoted = recent.rsplit('“', 1)[-1]
            sentence = len(CJK.findall(quoted)) > 20 and '，' in quoted
            value = -0.08 if sentence else -0.55
            if len(token) > 1 and not token[1:].isspace():
                value *= 0.6
        else:
            value = -0.20
    state = (doc, count + 1, token, (recent + token)[-100:],
             only_returns and token == '\r')
    return state, value

"""Approximate a document-onset signal, not a topic detector.

The first token (and an uninterrupted initial repetition of it) gets a
shape/grammar estimate. Space-prefixed capitals are strongly positive,
especially short ones; digits and blanks are negative. Function-word
subclasses and a few familiar formatting markers refine that estimate.
There are two brief onset exceptions: a 2 following initial 1 digits, and
the colon of an initial "Title:" label. Everywhere else the prediction is
zero. Arbitrary word-piece-specific variation is left unexplained.
"""

READS = ()

PREPOSITIONS = set('of in on for from with as into over under through between '
                   'against about after before without within upon'.split())
PRONOUNS = set('it you we he she they me him her them us'.split())
MODALS = set('can could will would shall should may might must cannot'.split())
CONNECTIVES = set('if whether when while where because although though '
                  'unless until since than that which'.split())
DETERMINERS = set('a an the this these those any some each every all both '
                  'such another no'.split())
CAPTION_LABELS = set('Table Figure Fig FIG Eq Equation'.split())
FUNCTION_WORDS = (PREPOSITIONS | PRONOUNS | MODALS | CONNECTIVES | DETERMINERS
                  | set('and or but so not to is are be been being was were '
                        'am has have had do does did my your our '
                        'their its'.split()))


def onset(s):
    word = s.strip()
    low = word.lower()
    spaced = s.startswith(' ')
    if s == ' The':
        return 14.5
    if s == ' A':
        return 4.5
    if spaced and word in CAPTION_LABELS:
        return 8.0
    if word.istitle() and spaced and len(word) > 1:
        if low in PRONOUNS:
            return 8.2 if low == 'we' else 3.5
        shortness = 6.5 if len(word) <= 3 else max(1.7, 8.2 - len(word))
        boost = 0.0
        if low in PREPOSITIONS:
            boost = 3.0
        elif low in FUNCTION_WORDS:
            boost = 1.3
        return shortness + boost
    if not word:
        return -0.5
    if word.isdecimal():
        return -0.65
    if low in PREPOSITIONS:
        return 3.75 if low == 'of' else 1.9
    if low == 'to':
        return -1.27
    if low in {'me', 'him', 'them', 'us'}:
        return 1.0
    if low in {'my', 'our'}:
        return 3.5
    if low in {'his', 'her'}:
        return 2.2
    if low in PRONOUNS or low in MODALS:
        return -0.8
    if low == 'i':
        return 0.0
    if low in {'is', 'are', 'be', 'been', 'being', 'am'}:
        return -0.8
    if low in {'was', 'were', 'has', 'have', 'had'}:
        return 0.0
    if low in {'a', 'the', 'this'}:
        return -1.7 if low == 'a' else -0.4
    if low in {'an', 'all', 'some', 'each', 'every', 'no', 'these', 'those'}:
        return 2.6
    if low in {'any', 'both'}:
        return 1.0
    if low in {'do', 'does', 'did'}:
        return 2.7
    if low == 'such':
        return 7.3
    if low == 'so':
        return 4.6
    if low == 'but':
        return 2.6
    if low in CONNECTIVES:
        return 1.9
    if low in {'and', 'or', 'not'}:
        return -0.55
    if low in {'at', 'by', 'your', 'their', 'its'}:
        return 0.9
    if s.startswith('<|'):
        return -2.8 if s == '<|endoftext|>' else 0.25
    if not any(c.isalpha() for c in word):
        if word == '**':
            return 11.4
        if spaced and word.startswith('$'):
            return 4.0
        if '^' in word:
            return 5.0
        if spaced and word in {'=', '+', '*'}:
            return -1.7
        if spaced and word == '<':
            return 3.4
        if spaced and word == '(':
            return 3.0
        if word in {'"', "'", '“', '‘'}:
            return 1.7
        return 0.0
    if len(word) == 1 and word.isascii():
        return 1.2 if spaced and word.isupper() else -1.0
    if word.isupper():
        return 2.1 if spaced else 1.0
    if word.isascii() and word.isalpha():
        base = 1.6 if spaced else 2.3
        return max(-0.2, base - 0.22 * len(word))
    return 0.9


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        return (document, 1, s, token, True), onset(s)
    document, position, first, first_token, initial_run = carry
    value = 0.0
    if initial_run and token == first_token:
        value = onset(s)
    elif initial_run and first == '1' and s == '2':
        value = 3.6
    elif position == 1 and first == 'Title' and s == ':':
        value = 15.3
    initial_run = initial_run and token == first_token
    return (document, position + 1, first, first_token, initial_run), value

"""A local spelling-fragment detector, not a calculator.

The main positive pattern is L--O--R, often split between subwords.
Calculator/calorie fragments and weaker L--OUR/LEUR relatives also fire.
Lure, lull and Lille-like continuations have the opposite sign. Common
unsplit color words do not fire. Values are approximate training means;
unmatched text is assigned zero. Only the previous token is retained.
"""
from functools import lru_cache
import regex as re
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(raw):
    # Transliteration is useful for alphabetic scripts, not Han readings.
    if re.search(r'\p{Han}|\p{Hiragana}|\p{Katakana}', raw):
        return ''
    return anyascii(raw).lower()


@lru_cache(maxsize=32768)
def unsplit(raw):
    t = spelling(raw)
    s = t.strip()
    if s == 'calculator':
        return 4.6
    if s == 'calor':
        return 4.8
    if s in ('calorie', 'calories'):
        return 1.8
    if raw.strip() == 'calcul':
        return 2.4
    if s != 'color' and re.fullmatch(r'[a-z]{0,2}lor', s):
        return 3.6 if t == 'lor' else 2.2
    if s == 'loro':
        return 3.2
    if re.fullmatch(r'[a-z]{0,2}lors', s):
        return 1.9
    if re.fullmatch(r'[a-z]{0,2}lore', s):
        return 1.3
    if re.fullmatch(r'f?lour', s):
        return 1.3
    if re.fullmatch(r'[a-z]{1,3}leurs?', s) or re.fullmatch(r'leurs?', t):
        return 1.8
    if re.fullmatch(r'(al)?lur(e|ed|es|ing)', s):
        return -3.1
    return 0.0


def boundary(prev_raw, raw):
    p, t = spelling(prev_raw), spelling(raw)
    if p.endswith('calcul') and t.startswith('ator'):
        return 5.4
    if (p.endswith('cal') and t.startswith('culator')
            or p.endswith('calc') and t.startswith('ulator')):
        return 5.4
    if p.endswith('l'):
        if re.fullmatch(r'or([aeiousy]|ic|ie|ies|es|ia|en|d|r|um|us|is)?', t):
            if p.endswith(('cal', 'kal')):
                return 8.0 if t == 'oric' else 5.3
            if p.endswith('ill'):
                return 2.0
            if raw.startswith('ор') and t != 'oro':
                return 5.2
            return 2.1 if t == 'ora' else 3.3
        if p.strip() in ('l', 'all') and re.fullmatch(r'ur(e|ed|es|ing)', t):
            return -5.0
        if t.startswith('ull'):
            return -5.1
        if t in ('ill', 'ille'):
            return -3.8
        if t.startswith('our'):
            return 1.9
        if raw.startswith('ь'):
            return -1.3
        if raw.startswith(('ự', 'ục')):
            return -3.8
        if raw in ('ر', 'ار'):
            return 1.1
    if p.endswith(('la', 'le')) and re.fullmatch(r'ur([aeonsy]|en)?', t):
        return 2.6
    if p.endswith('lu') and t.startswith('or'):
        return 1.6
    if re.search(r'l[ao]$', p) and re.match('r[a-z]', t):
        return 0.8
    if p.endswith(('ch', 'lk')) and t == 'lor':
        return 5.2
    if p.endswith('lor') and t in ('o', 'ic', 'ii', 'ia'):
        return 2.2
    # Thai tone/vowel continuations after the L consonant.
    if prev_raw.endswith('ล') and raw in ('่า', '่อ', '้ำ'):
        return -8.0
    return None


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    value = boundary(prev, raw)
    if value is None:
        value = unsplit(raw)
    return (doc, raw), value

programs.haiku:
"""Money amounts. The component goes negative on a currency sign that starts a price (most
after "more than", "at", "for", "about"), on the digits of the amount that follows it, and
on money words such as "million" or "dollars". It is near zero in LaTeX, code and
variable names, where "$" is not a price."""
READS = ()

# Currency signs and units. A bare "$" with no space is left out: it is mostly LaTeX or code.
CURRENCY = {" \\$", "\\$", " £", "£", " €", "€", " ¥", "¥", "￥", " ₹", "₹",
            "円", "元", "万元", "亿元", "ドル", " Rs", "Rs", " руб", "₽"}
# Words for an amount of money, strong and weaker ones.
MONEY_WORDS = {" million", " billion", " dollars", " dollar", " euros", " euro", " Euro", " bucks"}
SOFT_MONEY_WORDS = {" money", " funding", " cent", " cents", " fee", " budget", " cost", " costs",
                    " price", " pounds", " worth"}
# Words that lead into a number: "more than $", "at $", "for $" are the strongest cases.
QUANTITY_BEFORE = {" than", " about", " at", " to", " for", " over", " approximately"}
# Words before a dollar sign in code, lists or maths, where the sign is not a price.
NOT_MONEY_BEFORE = {",", " and", " that", " with", " as", " =", " (", " =>", " where", " then",
                    " return", "\n", "\t", " ,", " or", " in"}
# Signs of LaTeX or code: a dollar sign near these is not a price.
MATH_MARKS = ("\\", "{", "}", "^")


def in_maths_or_code(toks):
    """True when the recent text looks like LaTeX or code, not prices."""
    recent = toks[-31:-1]
    if any(any(m in s for m in MATH_MARKS) for s in recent if s not in (" \\$", "\\$")):
        return True
    # Earlier dollar signs: one followed by a digit is a price, one followed by anything else is maths.
    prices = maths = 0
    for i in range(max(0, len(toks) - 31), len(toks) - 1):
        if toks[i] in (" $", " \\$", "\\$") and i + 1 < len(toks) - 1:
            if toks[i + 1].strip().isdigit():
                prices += 1
            else:
                maths += 1
    return maths > prices


def step(carry, prefix, upstream):
    """carry: how many digits have followed the last currency sign, or None outside an amount."""
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    new_doc = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    digits = None if new_doc else carry
    if in_maths_or_code(toks):
        return None, 0.0
    if tok == " $":
        if prev in NOT_MONEY_BEFORE:
            return 0, 0.0
        return 0, (-8.0 if prev in QUANTITY_BEFORE else -4.0)
    if tok in CURRENCY:
        return 0, -5.0
    if digits is not None:
        if len(tok.strip()) == 1 and tok.strip().isdigit():
            digits += 1
            return digits, (-5.0 if digits == 1 else (-3.5 if digits == 2 else -2.0))
        if tok in (",", ".", " "):
            return digits, -1.0
    if tok in MONEY_WORDS:
        return None, -3.5
    if tok in SOFT_MONEY_WORDS:
        return None, -1.5
    return None, 0.0

programs.sol:
"""A sparse spelling heuristic, not a semantic classifier.

Track the current word. A-like continuations after -nt/-st tend negative;
-ent/-ant/-int and -il continuations after consonant clusters tend positive.
A few strong spelling families receive separate gains. Document starts have
an additional negative baseline depending on whitespace, length and digits.
These are approximate tendencies, not a complete account of the component.
"""
import re
from anyascii import anyascii

READS = ()

# Word stems, also covering inflections and words split over several tokens.
FAMILIES = (
    ('contam', -3.85),
    ('confront', -2.22),
    ('contempl', -0.81),
    ('entrai', -1.05),
    ('incent', 1.63),
    ('consent', 0.72),
    ('extent', 1.05),
    ('inset', 1.05),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, word = '', 0, ''
    else:
        _, previous, position, word = carry
    text = prefix.token_strings[-1]
    pieces = re.split(r'[^\w]+', text)
    word = pieces[-1] if len(pieces) > 1 else word + text
    s = anyascii(text).lower()
    w = anyascii(word).lower()
    p = anyascii(previous).lower().rstrip()
    if s and s[0].isalpha() and w.endswith(s):
        p = w[:-len(s)] or p
    value = sum(gain for stem, gain in FAMILIES if w.startswith(stem))

    internal = (s and s[0].isalpha() and previous
                and previous[-1].isalpha())
    if internal:
        a_like = re.match(r'a(?:l|m|in|is|e|n(?!t))', s)
        if a_like and p.endswith('nt'):
            value -= 0.42
        elif a_like and p.endswith('st'):
            value -= 0.18
        if p.endswith('nt') and s.startswith('in'):
            value -= 0.17
        if p.endswith(('nt', 'st', 'rt', 'ct', 'tr')):
            if s.startswith(('ant', 'ent', 'int', 'nt')):
                value += 0.65
            if s.startswith(('il', 'ier')):
                value += 0.45
            if s.startswith(('or', 'ur', 'av', 'ar', 'et', 'ax')):
                value += 0.085
        if p.endswith('ext'):
            value += 0.09
        if p.endswith('cont') and s.startswith('am'):
            value -= 2.04

    if position == 0:
        value -= 0.27
        if text[:1].isspace():
            value -= 0.33 if len(text.strip()) > 3 else 0.15
        if text.isdigit():
            value -= 0.31
    return (doc, text, position + 1, word[-48:]), float(value)

"""Detect short 'eg' spelling pieces and e-to-g token boundaries.

The response is mostly negative. Longer pieces respond less; another g
nearby strengthens it. Cyrillic spelling is included by transliteration.
Accented vowel-g pairs get separate corrections. This is a spelling
approximation, not a word-meaning detector.
"""
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=65536)
def describe(text):
    alphabetic = all(
        ord(c) < 128 or any(script in unicodedata.name(c, '')
                           for script in ('LATIN', 'GREEK', 'CYRILLIC',
                                          'FULLWIDTH'))
        for c in text
    )
    normalized = anyascii(text).lower() if alphabetic else text.lower()
    piece = normalized.strip()
    n = len(piece)
    value = -0.0004
    if 'g' in piece:
        if n <= 3:
            value -= 0.066
        if piece.count('g') >= 2 and n <= 4:
            value -= 0.675
        if 'eg' in piece:
            value -= {2: 2.304, 3: 0.905, 4: 0.476}.get(n, 0.0)
            if piece.endswith('eg'):
                value -= 0.145
            if piece.startswith('eg'):
                value -= 0.320
            if zipf_frequency(piece, 'en') < 3:
                value -= 0.364
            if any('CYRILLIC' in unicodedata.name(c, '') for c in text):
                value += 0.682
            if 'ég' in text.lower():
                value += 0.990
        if 'ág' in text.lower():
            value += 1.282
    return normalized, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = ''
    if carry is not None and carry[0] == doc:
        previous = carry[1]
    text, value = describe(prefix.token_strings[-1])
    n = len(text.strip())
    if text and text[0].isalpha():
        if text.startswith('g') and previous.endswith('e'):
            value -= 1.997
            if n >= 4:
                value += 1.643
            if 'g' in previous:
                value -= 2.383
        if previous.endswith('eg') and n <= 2:
            value -= 1.005
        if previous.endswith('g') and text[0] in 'aeiou':
            value -= 0.099
    return (doc, text), float(value)

"""Recognize written binary operations and word-alternative slashes.

Set intersection/union, products, direct sums and related LaTeX commands have
separate strengths. Products of symbolic operands are stronger than ordinary
numeric multiplication. A slash joining words is stronger than a URL, path
or fraction slash. The colon in a document-initial 'Title:' is a separate,
large negative response. Other text is approximated by zero.
"""
import re
import unicodedata

READS = ()

# Binary mathematical operations, not arbitrary vocabulary items.
SYMBOLS = {
    '∩': 8.0, '∪': 5.8, '⋂': 8.0, '⋃': 6.0,
    '∖': 8.0, '∐': 4.3, '⊕': 4.5, '⊖': 2.3,
    '⊗': 3.7, '⊙': 2.8, '⋊': 10.9, '⋉': 9.0,
    '∧': 1.8, '∨': 2.3, '∘': 1.2, '⋅': 1.7,
    '⋆': 2.2, '⊔': 5.0, '⊓': 7.0,
}
# Values are attached to readable command fragments because commands may
# span multiple tokens: e.g. set + minus, opl + us, w + edge.
COMMANDS = {
    'cap': 8.5, 'cup': 6.3, 'set': 2.8, 'setminus': 8.4,
    'back': 2.4, 'backslash': 8.5, 'opl': 2.2, 'oplus': 6.2,
    'ot': 4.5, 'otimes': 6.5, 'odot': 2.1, 'ominus': 6.1,
    'w': 0.4, 'wedge': 3.5, 'vee': 5.6, 'land': 4.9,
    'am': 3.4, 'amalg': 2.0, 'leftrightarrow': 1.6,
    'cdot': 1.4, 'circ': 3.7, 'star': 2.0, 'ast': 1.1,
    'sq': 1.9, 'sqcup': 6.0, 'sqcap': 8.0,
    'rtimes': 10.0, 'ltimes': 8.0,
    'over': -1.7, 'eps': -3.5, 'to': -0.5,
    'cr': -0.8, 'rf': 0.8, 'pmod': 1.0, 'bmod': 1.0,
    'smallcaps': 1.4,
}


def variable_letters(word):
    """A single variable letter, or a capital pair naming a vector."""
    short = len(word) == 1 or len(word) == 2 and word.isupper()
    return short and all(c.isalpha() and any(script in
        unicodedata.name(c, '') for script in
        ('LATIN', 'GREEK', 'MATHEMATICAL')) for c in word)


def product_strength(before):
    """Distinguish a symbolic operand from an ordinary numeral."""
    operand = before.rstrip()
    word = re.search(r'([^\W_]+)$', operand)
    if word:
        word = word.group()
        if word.isalpha():
            if re.search(r'(?:[0-9]\s*|/)(?:g|kg|L|mL|mm|cm|m|s)$', operand):
                return 0.25
            return 3.7 if variable_letters(word) else 0.25
        match = re.fullmatch(r'([^\W\d_])([0-9]{1,2})', word)
        if match:
            return 4.5
        return 0.65
    if operand.endswith(('}', ')', ']', '|')):
        return 2.8
    return 0.65


def predict(b, history, position):
    s = b.decode('utf-8', 'ignore')
    before = history.decode('utf-8', 'ignore')
    if position == 1 and before == 'Title' and s == ':':
        return -9.8
    if '\x0c' in s:
        return 0.75
    if s.strip() == '··':
        return -1.14
    if b and b[0] & 0xc0 == 0x80:
        s = (history[-3:] + b).decode('utf-8', 'ignore')[-1:]
    glyph = s.strip()
    if glyph in SYMBOLS:
        return SYMBOLS[glyph]
    if glyph == '×':
        return 3.7 if position == 0 else product_strength(before)
    if glyph == '○':
        return 4.2 if product_strength(before) > 3 else 0.1
    if glyph == '÷':
        return 0.9
    if glyph in ('·', '•'):
        word = re.search(r'([^\W_]+)\s*$', before)
        if word and variable_letters(word.group(1)):
            return 2.2 if glyph == '·' else 1.2
        if glyph == '·' and before.rstrip().endswith(('}', ')', ']', '|')):
            return 2.0
        return -0.12
    # An unfinished UTF-8 prefix in the mathematical-operator block.
    if b.endswith(b'\xe2\x8b'):
        return 2.3
    if s.isascii() and s.isalpha():
        command = re.search(r'\\([A-Za-z]*)$', before)
        if command:
            name = command.group(1) + s
            name = re.sub(r'^(?:bigg|Bigg|big|Big)', '', name)
            if name == 'times':
                operand = before[:command.start()]
                return product_strength(operand) + 0.5
            if name == 'circ' and before[:command.start()].rstrip().endswith('^'):
                return 0.0
            return COMMANDS.get(name, 0.0)
    if '/' in s and not s.startswith(('//', '/*', '</', '/>')):
        left = before + s[:s.index('/')]
        word = re.search(r'([^\W\d_]+)$', left)
        if word:
            recent = left[-70:]
            path = re.search(r'https?://|www\.|[/\\_]|[=<>]', recent)
            if not path:
                if s == '/or' and word.group() == 'and':
                    return 0.56
                text = word.group()
                if text.lower() in {
                    'he', 'she', 'his', 'her', 'him', 'they', 'their',
                    'is', 'are', 'was', 'were', 'and', 'or',
                }:
                    return 0.65 if s.strip() == '/' else 0.95
                if 'CJK' in unicodedata.name(text[-1], ''):
                    return 0.6
                if text.isupper() and len(text) >= 2:
                    return 0.55
                length = len(text)
                if s.strip() == '/':
                    return 0.4 if length >= 5 else 0.15
                return 0.9 if length >= 3 else 0.3
    if s == 'caps' and before.endswith('.small'):
        return 1.4
    if s == '#' and re.search(r'[A-G]$', before):
        return 0.45
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history, position = b'', 0
    else:
        _, history, position = carry
    token = prefix.token_bytes[-1]
    value = predict(token, history, position)
    return (document, (history + token)[-160:], position + 1), value

"""Quantity/order context followed by an English modifier.

Recognize numbers, quantifiers, ordinals and extrema, including 'number of'.
They amplify 'such' and semantic families of descriptors. Other WordNet
adjectives receive a small response. Numeric continuations after first/last
instead receive a negative response. Keep two nonblank tokens of context,
resetting at document boundaries. This only approximates the component.
"""
from functools import lru_cache
import inflect
import wordnet

READS = ()
_engine = inflect.engine()
NUMBERS = frozenset(_engine.number_to_words(n).removeprefix('one ')
    for n in (*range(21), 30, 40, 50, 60, 70, 80, 90, 100,
              1000, 1000000, 1000000000, 1000000000000))
ORDINALS = frozenset(_engine.number_to_words(_engine.ordinal(n))
                     for n in range(1, 21))
QUANTIFIERS = frozenset('''no any every each all both either neither some
    several many few fewer less more most least much little enough various
    multiple numerous certain single'''.split())
CONTEXT = {
    'first': 1.0, 'second': .53, 'last': .64, 'next': .96,
    'current': .75, 'no': .67, 'any': .52, 'each': .57,
    'every': .41, 'all': .57, 'only': .25, 'other': .35,
}
# Family-specific responses: possibility, knowledge, reality, extent,
# importance, difference, availability, activity, continuity, persistence,
# and authority, respectively.
DESCRIPTORS = (
    (3.9, 'possible impossible feasible potential probable plausible'),
    (2.3, 'known unknown documented recorded reported'),
    (2.9, 'real actual true genuine'),
    (2.3, 'full complete entire whole partial'),
    (2.8, 'main major great significant important principal primary key'),
    (2.1, 'different distinct unique separate independent'),
    (2.8, 'available free valid accessible usable'),
    (2.8, 'working active operational functioning'),
    (1.7, 'straight consecutive successive continuous'),
    (2.1, 'surviving remaining existing living'),
    (1.7, 'official authorized formal'),
)
DESCRIPTORS = tuple((v, frozenset(s.split())) for v, s in DESCRIPTORS)


@lru_cache(None)
def context_strength(w):
    if w in CONTEXT:
        return CONTEXT[w]
    if w in ORDINALS or w in {'th', 'st', 'nd', 'rd', 'previous', 'final', 'initial'}:
        return .41
    if w in NUMBERS:
        return .70
    if w.isdecimal():
        return .22
    if w in QUANTIFIERS:
        return .16
    if w in {'top', 'minimum', 'maximum', 'minimal', 'maximal'}:
        return .71
    if w.isascii() and w.isalpha() and 'adjective' in wordnet.parts_of_speech(w):
        if w.endswith('est'):
            return .61
        if w.endswith('er'):
            return .10
    return 0.0


@lru_cache(None)
def descriptor(w):
    for value, words in DESCRIPTORS:
        if w in words:
            return value
    if w.isascii() and w.isalpha() and w not in NUMBERS:
        pos = wordnet.parts_of_speech(w)
        if 'adjective' in pos and not w.endswith('er'):
            return .4
        if 'verb' in pos and w.endswith(('ed', 'ing')):
            return .15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    last, before = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    strength = context_strength(last)
    if last == 'of' and before in {'number', 'numbers', 'amount', 'quantity',
                                   'count', 'total', 'level'}:
        strength = .73
    token = prefix.token_strings[-1]
    w = token.strip().lower()
    value = strength * descriptor(w.strip('_-'))
    if w == 'such':
        if last.isdecimal() or last in NUMBERS:
            value = 5.0
        elif last == 'of' and strength > .5:
            value = 6.0
        elif last in ORDINALS or last in {'last', 'next'}:
            value = 8.0
        else:
            value = 7.0 if strength >= .15 else 0.0
    elif last in {'first', 'last', 'next', 'top'}:
        if token == ' ':
            value = {'first': -.63, 'last': -1.2, 'next': -.2, 'top': -1.0}[last]
        elif w.isdecimal() or w in NUMBERS:
            value = -.6 if last in {'first', 'last'} else -.2
    elif w == 'one' and last in {'any', 'no'}:
        value = 1.5
    if w:
        before, last = last, w
    return (doc, last, before), float(value)

"""A written climate-root detector with weaker syllable responses.

Climate/climat/clima, Germanic 'klim-', Russian 'клим-', and the
East Asian climate characters are the main positive cues.  Split roots
can respond both on their first fragment and on their continuation.
The bare character 候 is a weaker positive cue.  Isolated Japanese mi
syllables and romanized umi/omi pieces are negative cues.  The み
response is stronger after another hiragana, except after て/で.
The umi fragment is more negative after a multi-letter Latin stem.
Other positions receive zero.  State resets at document boundaries.
"""
import regex as re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    t = token.lower()
    text = old + t
    value = 0.0

    # Whole words and subwords are different-strength cues.
    if re.search(r'[ck]limat', t):
        value = 7.5
    elif re.search(r'[ck]lim$', t):
        value = 3.0 if token.strip().istitle() else 5.2
    elif not token.istitle() and any(m.start() < len(old) < m.end()
             for m in re.finditer(r'[ck]lim', text)):
        value = 9.0 if t.startswith(('ima', 'lim')) else 7.0
        if t.startswith('imb'):
            value = 0.8
    elif re.search(r'[ck]lim$', old) and t.startswith('a'):
        value = 10.0 if t.startswith('at') else 6.0

    if 'клим' in text and 'клим' not in old:
        value = 15.0 if t.startswith('мат') else 7.5
    elif old.endswith('клим') and t.startswith('ат'):
        value = 6.0
    if token in ('气候', '氣候', '気候'):
        value = 6.1
    elif token == '候':
        value = 13.0 if old.endswith(('气', '氣', '気')) else 3.0

    if token == 'み':
        if (re.fullmatch(r'\p{Script=Hiragana}', old[-1:])
                and not old.endswith(('て', 'で'))):
            value = -4.45
        else:
            value = -2.25
    elif token == 'ミ':
        value = -1.5
    elif token == 'のみ':
        value = -1.9
    elif token == 'umi':
        stem = re.search(r'[a-z]+$', old)
        value = -4.6 if stem and len(stem[0]) > 1 else -1.7
    elif token == 'omi':
        value = -2.5
    return (doc, text[-16:]), value

programs.haiku:
"""Climate-word detector (v3).

Reads the word being typed (letters since the last non-letter) and fires when it spells
'climate' or a stem of it, in English and other languages. Values are the typical activations
observed at each spelling (in the training text). A second, weaker effect is negative: the
Japanese kana 'み', 'ミ', 'む' and the 'umi' / 'mi' sounds."""

READS = ()

# spelled-out climate words and stems -> typical activation
CLIMATE = {
    "clim": 4.0, "clima": 9.0, "climat": 12.0, "climate": 8.0, "climates": 7.0, "climatic": 9.0,
    "klim": 8.0, "klima": 9.0, "klimat": 10.0, "клим": 6.0, "климат": 15.0,
    "气候": 6.0,
}
# Japanese 'mi' / 'mu' syllables and 'umi' -> typical (negative) activation
MI_SOUNDS = {"み": -2.7, "ミ": -1.8, "む": -1.0, "umi": -2.1, "mi": -0.4}


def current_word(text):
    word = ""
    for ch in reversed(text):
        if not ch.isalpha():
            break
        word = ch + word
    return word.lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MI_SOUNDS:
        return None, MI_SOUNDS[token]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        text = token                                  # a new document starts here
    else:
        text = prefix.text_prefixes[-1]
    word = current_word(text)
    if word.endswith("气候"):
        return None, CLIMATE["气候"]
    return None, CLIMATE.get(word, 0.0)

programs.sol:
"""A document-onset feature with lexical and formatting polarity.

Only the first token of each visible document gets a large response. Definite
articles, possession, containment, imports and headings tend to be positive;
indefinite articles, copulas and selected question/code forms are negative.
These are coarse word-class rules, not a complete token lookup. Smaller
within-document activations are not reconstructed.
"""
READS = ()


def onset(s):
    word = s.strip()
    lower = word.lower()
    spaced = s.startswith((' ', '\t'))
    capital = word[:1].isupper()

    if s == '<|endoftext|>':
        return -4.0
    if s.startswith('<|'):
        return -0.42
    if word and set(word) == {'#'}:
        return 3.53 if len(word) == 1 else 2.21 if len(word) == 2 else 0.65
    if s in ('package', 'import', 'from', 'using', 'use', 'require'):
        return 4.1
    if s == 'def':
        return 4.3
    if s.startswith('/*'):
        return 3.0 if '\n' in s else -1.0
    if s == '//':
        return 3.35
    if s.startswith('//') and '\n' in s:
        return -5.15
    if s.startswith('#!'):
        return 2.8
    if s == '#define':
        return -6.0
    if s == '#pragma':
        return 2.5
    if s == '\\n':
        return -4.88
    if lower == 'the':
        return 0.33 if word.isupper() else 2.0 if capital else 2.94 if spaced else 3.43
    if lower in ('ein', 'eine'):
        return -4.7
    if lower == 'a':
        return -2.3 if spaced else -0.59 if capital else 0.37
    if lower == 'an':
        return -0.5 if spaced or capital else 0.71
    if lower in ('is', 'be', 'been'):
        return 0.8 if capital and lower == 'is' else -3.1 if spaced else -1.5
    if lower in ('was', 'were', 'are', 'have', 'has', 'had'):
        return 0.7 if capital and lower == 'are' else -1.5
    if lower in ('my', 'our', 'your', 'their', 'his', 'her', 'its'):
        return 2.85 if lower == 'my' and not capital else 1.5 if capital else 1.75
    if lower == 'this':
        return -0.4
    if lower in ('that', 'these', 'those'):
        return 0.5 if word == 'These' else 2.0
    if lower in ('he', 'she', 'we', 'they', 'i'):
        return -0.8
    if lower in ('in', 'of', 'from'):
        return 2.33 if lower == 'of' else 2.08 if not spaced and lower == 'in' else 1.5
    if lower == 'as':
        return -1.2
    if lower == 'if':
        return 1.45
    if lower == 'so':
        return -0.85
    if lower in ('and', 'or'):
        return 0.0 if spaced else 1.2
    if lower in ('to', 'for', 'with', 'at', 'on'):
        return 0.5
    if lower in ('do', 'does', 'did'):
        return 3.6 if word == 'Do' else 1.8
    if lower == 'what':
        return 2.4
    if lower == 'how':
        return -1.9 if capital else 0.0
    if lower == 'get':
        return -4.9 if spaced or capital else -2.0
    if lower in ('show', 'showing'):
        return 3.5
    if lower in ('return', 'break'):
        return -5.5 if spaced else -1.5
    if lower in ('true', 'false', 'null'):
        return -5.5 if lower == 'null' else -2.8
    if word in ('&&', '||', '==', '!='):
        return -3.4
    if word == '=':
        return -1.7 if spaced else -0.46
    if word == '?':
        return -3.3 if '\n' in s else -2.2
    if word in ('(', '[', '<'):
        return 0.6 if s == '(' else 1.8
    if word in ('.', ';', ':'):
        return -1.0 if '\n' in s else 0.3
    if word == ',':
        return -0.38
    if s.isspace() or word.isdigit():
        return -0.15
    return 0.25 if capital else 0.0


def step(carry, prefix, upstream):
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, onset(prefix.token_strings[-1]) if start else 0.0

programs.haiku:
"""layers.1.mlp.down_proj:1933 — a "document-opening word" detector.

What it does: the component is almost silent inside a document, but at the first
token of each document (the first token after a document break, or the first token
of a row) it writes a value that depends on what kind of word that token is:

  * code and markup openers ('#', '//', 'import', 'package', 'using', 'def', '/*')
    -> strongly positive (about +3);
  * determiners, possessives, quantifiers and prepositions that open a phrase
    ('The', ' the', ' these', ' my', ' all', ' of', ' in', ' from', ' with') -> positive (about +2.2);
  * auxiliaries, copulas, subject pronouns, and 'a'/'as'/'=' (' is', ' be', ' was',
    ' have', ' a', ' as', 'I', 'He') -> negative (about -2.3);
  * every other token, and every token inside a document -> 0.

The values are class means measured on training text. The program needs no state
beyond the document-boundary check: it reads only the newest token.
"""

READS = ()

# code and markup openers
CODE_OPENERS = {
    "#", "##", "#!/", "#include", "#define", "#pragma", "//", "/*", "/*\n", "/**\n",
    "--", "__", "import", "package", "using", "def", "from", "use", "namespace", "main",
    "print", "int", "str", "show", "Show", "Showing", "[", "<",
}
# determiners, possessives, quantifiers, prepositions and phrase-opening words
PHRASE_OPENERS = {
    " the", "The", " The", "the", " of", " in", "In", "in", " that", "That", " (",
    " these", " those", " my", "My", " our", " your", " their", " some", " all", " two",
    " first", " do", "Do", "What", "Title", "Today", "Use", " from", " if",
}
# auxiliaries, copulas, subject pronouns, 'a', 'as', and clause-continuing verbs
CLAUSE_WORDS = {
    " is", " be", " been", " was", " are", " were", " have", " has", " had", " seem",
    " also", " true", " as", "As", " a", " A", " =", " return", "\treturn", "Get", " Get",
    "Explore", "How", "By", " too", " continue", ";\n", ".\n", "?", "\\n",
}


def step(carry, prefix, upstream):
    # Only the first token of a document (or of the row) can be nonzero.
    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0
    word = prefix.token_strings[-1]
    if word in CODE_OPENERS:
        return None, 3.1
    if word in PHRASE_OPENERS:
        return None, 2.2
    if word in CLAUSE_WORDS:
        return None, -2.3
    return None, 0.0

programs.sol:
"""Approximate an English third-person-singular verb signal.

Recognize s/es/ies inflections with WordNet and spelling rules. Pronoun subjects
and short determiner+noun phrases support a verbal reading; adjectives support
an ordinary plural reading instead. Frequency and token spacing set the size.
These are coarse local cues, not a full parser; incomplete words are not modeled.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
DETERMINERS = set('''a an the this that these those my your his her its our their
some any all no each every both other such many few several more most much less'''.split())
PREPOSITIONS = set('''of in on at to for with from by as into through over under
about between after before without within than per'''.split())
AUXILIARIES = set('''is are was were be been being has have had do does did can
could would should shall will may might must'''.split())
SUBJECTS = set('''he she it this that who which someone anyone everyone nobody
somebody something anything everything one'''.split())
FUNCTIONS = DETERMINERS | PREPOSITIONS | AUXILIARIES | set('''us thus yes always
sometimes perhaps nevertheless whereas unless plus minus news'''.split())

@lru_cache(maxsize=30000)
def parts(word):
    return wordnet.parts_of_speech(word)

@lru_cache(maxsize=30000)
def verb_form(word):
    """Find a verb whose regular singular-present spelling is this word."""
    bases = []
    if len(word) > 2 and word.endswith('s') and word not in FUNCTIONS:
        for base in wordnet.base_forms(word):
            if 'verb' not in parts(base):
                continue
            if base.endswith('y') and len(base) > 1 and base[-2] not in 'aeiou':
                form = base[:-1] + 'ies'
            elif base.endswith(('s', 'x', 'z', 'ch', 'sh', 'o')):
                form = base + 'es'
            else:
                form = base + 's'
            if word == form:
                bases.append(base)
    if word == 'does':
        bases = ['do']
    return max(bases, key=lambda b: zipf_frequency(b, 'en')) if bases else None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    tail = (tail + token)[-180:]
    carry = (doc, tail)
    match = re.search(r'([A-Za-z]+)$', tail)
    if not match or not re.search(r'[A-Za-z]$', token):
        return carry, 0.0021
    word = match[1].lower()
    base = verb_form(word)
    if base is None:
        plural = (len(word) > 2 and word.endswith('s')
                  and word not in FUNCTIONS and 'noun' in parts(word))
        return carry, 0.0274 if plural else 0.0021

    context = tail[:match.start()]
    words = re.findall(r'[A-Za-z]+', context)[-6:]
    if not any(zipf_frequency(w.lower(), 'en') > 4 for w in words):
        return carry, 0.0021
    previous = re.findall(r'[A-Za-z]+|[0-9]+|[^\w\s]', context)
    prev = previous[-1].lower() if previous else ''
    before = previous[-2].lower() if len(previous) > 1 else ''
    noun_reading = 'noun' in parts(word)
    attached = not token[0].isspace()
    frequency = zipf_frequency(word, 'en')
    base_frequency = zipf_frequency(base, 'en')

    if prev in SUBJECTS:
        if attached:
            value = 1.672
        elif not noun_reading:
            value = 0.2921
        elif base_frequency > 5.61:
            value = 0.4047
        else:
            value = 1.0858 if 'noun' in parts(prev) else 0.727
    elif not noun_reading:
        if frequency >= 4.48:
            value = 0.2085
        elif frequency >= 3.392:
            value = 0.4947
        else:
            value = 1.0805 if attached else 0.6172
    elif before in DETERMINERS:
        if 'adjective' in parts(prev):
            value = 0.0595
        else:
            value = 0.5646 if 'noun' in parts(prev) else 0.1288
    else:
        value = 0.2248 if base_frequency > 5.62 else 0.085
    return carry, value

"""A token-shape-dependent pulse at the beginning of each document.

The pulse persists while the initial token is repeated, then becomes zero.
Hyphenated fragments, escapes, paths and delimiters have larger pulses.
Ordinary letters/words use script, case and English word frequency instead.
Training activations concentrate at document starts. These broad categories
model their varying strength without memorizing individual token identities.
"""
import re
import regex
from wordfreq import zipf_frequency

READS = ()

FILE_ENDINGS = {
    '.h', '.c', '.cpp', '.js', '.ts', '.php', '.py', '.rs', '.go',
    '.java', '.css', '.html', '.json', '.xml', '.md', '.txt', '.yml',
    '.yaml', '.sh', '.rb', '.png', '.jpg', '.pdf', '.com', '.org', '.net',
}


def pulse(s):
    t = s.strip()
    if s.startswith('<|'):
        return 0.059
    if not t:
        return 0.148
    if t.isdigit():
        return -0.477
    # Hyphenated word fragments and command-line options.
    if re.match(r'-[A-Za-z]', t):
        return 10.824 if t[1].isupper() else 14.611
    # Literal escape sequences; quoted and tab escapes are strongest.
    if '\\' in t:
        if re.search(r'''\\["']''', t):
            return 10.184 if s.startswith(' ') else 18.41
        if r'\t' in t:
            return 17.868
        return 2.848 if s.startswith(' ') else 6.187
    if '\n' in s or '\r' in s:
        return 0.995
    if re.match(r'/[A-Za-z]', t):
        return 6.445
    if t in FILE_ENDINGS:
        return 7.52
    if '^' in t:
        return 9.005
    if '{' in t or '}' in t:
        return 7.315
    if '"' in t or "'" in t or '’' in t:
        return 4.314
    if any(c in t for c in '<>&$%`!'):
        return 4.278
    if '\ufffd' in t:
        return 2.17
    if regex.search(r'\p{Script=Han}', t):
        return -0.367
    # Coarse lexical baseline for ordinary words and word fragments.
    if t.isalpha():
        if not t.isascii():
            return 1.103
        if len(t) == 1:
            return -0.611
        if t.isupper():
            return 0.499
        if t.istitle():
            return -0.203
        if zipf_frequency(t.lower(), 'en') >= 5:
            return 0.271
        return 1.757
    return 0.647


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = pulse(prefix.token_strings[-1])
        return (doc, token, value), value
    _, first, value = carry
    if token == first:
        return carry, value
    return (doc, None, 0.0), 0.0

programs.haiku:
"""Layer 1 MLP down_proj, component 1935: a document-start detector.

The component is silent inside a document. At the first token of each document, where
the model has no left context, it writes a value that depends on that token's text:
  - backslash escapes such as \\" or \\t: strongly positive (about +8);
  - a dash that starts a suffix piece ("-bottom", "-align"): strongly positive (about +10);
  - quotes and brackets, braces, slashes, colons and operators: moderately positive,
    rising with length;
  - lowercase word fragments with no space before them ("arian", "olph"): clearly positive
    when they are two or more letters;
  - whole words with a leading space: negative when a single letter (" a", " I"), rising
    toward about +1.3 for long words;
  - capitalised words and digits: slightly negative.
Everything else is near zero.
"""

READS = ()
SYMBOLS = '{}[]()/:*@^$=<>|&"\''


def value(s):
    """Activation for a token s (decoded alone) that starts a document."""
    word = s.strip()
    n = len(word)
    if '\\' in s:
        return 8.0
    if s.startswith('-') and n >= 2:
        return 10.0
    if not word:
        return 0.2
    if word.isdigit():
        return -0.5
    if word.isalpha():
        if s.startswith(' '):
            return min(0.3 * n - 0.6, 1.5)
        if word[0].isupper():
            return -0.4
        if n == 1:
            return -0.4
        return 2.2 if n <= 6 else 1.4
    if any(c in SYMBOLS for c in s):
        return min(1.5 * n, 4.0) if n <= 7 else 0.1
    return 0.5


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, float(value(prefix.token_strings[-1]))

programs.sol:
"""Exclamation versus negation, using nearby text rather than token identities.

Word-ending ! is positive. Expression-leading !, especially after if/while,
return, or a logical operator, is negative. The word 'not' is also negative
in conditional phrases, particularly at the start of a code line. Joined
quotes and newlines weaken the positive exclamation response. Other tokens
are left at zero. A short text tail is reset for each new document.
"""
import re

READS = ()


def predict(token, before):
    s = token.strip()
    if not ('!' in s or '！' in s or s.lower() == 'not'):
        return 0.0
    before = re.sub(r'\\([nrt])',
                    lambda m: '\t' if m[1] == 't' else '\n', before)
    b = before.rstrip()
    word = re.search(r'(\w+)\s*$', b)
    word = word[1] if word else ''
    code_line = re.match(r'\s*(?:\d+\s+)?(?:#\s*)?(if|elif|while)\b',
                         before.split('\n')[-1])
    if s.lower() == 'not':
        if word.lower() in {'if', 'elif', 'while', 'when'}:
            return -8.5 if code_line and word.islower() else -2.7
        if word.lower() in {'and', 'or'}:
            return -4.5 if code_line else -0.6
        return 0.0
    if '！' in s:
        return 1.0 if any(c in s for c in '”」』') else 2.2
    if '!=' in s or '<!--' in s or s.startswith('#!/'):
        return 0.0
    head, tail = s.split('!', 1)
    if '(' in head:
        return -8.5
    if '<' in head:
        return -9.0
    if tail.startswith('['):
        return -5.0
    if any(c in head for c in '/*#:&'):
        return -2.5 if '\n' in token else -5.0
    if head or '?' in s:
        return 0.0
    if token.startswith(' '):
        if word in {'if', 'while', 'return'} or b.endswith(('(', '&&', '||', '=')):
            return -5.0 if tail.startswith('!') else -10.5
        return -5.0 if b.endswith(':') else 0.6
    if b.endswith('['):
        return -9.0
    if before.endswith('\n'):
        return -5.5
    if not b:
        return -0.8
    if b[-1] in '(:=,&|#@\\' or word == 'return':
        return -6.0
    if '\n' in token:
        return 1.65
    if any(c in tail for c in '\"\'”’'):
        return 1.2
    if tail.startswith(('(', ')')):
        return 1.5
    return 0.5 if b[-1].isdigit() else 2.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-220:]), predict(token, before)

programs.haiku:
"""Exclamation marks, and "not" after "if".

This component reads the exclamation mark "!" in two roles and gives them opposite signs:
- "!" as a logical NOT in code (`if (!ok)`, `return !x`, `a && !b`): strongly negative.
- "!" ending an exclamation in ordinary prose or chat ("Great!", "Thanks!", "Oui !"):
  positive, strongest after a word of praise or agreement.
- "not" right after "if" / "when" (the English form of the same test): negative.
Other tokens are about zero, apart from the first token of a document (slightly negative).
Markup such as "<!--", "#!" or "/*!" and "!=" are ignored.
"""

READS = ()

# symbols or words after which a "!" is a code operator (or the start of a condition)
CODE_BEFORE = {"if", "while", "elif", "unless", "return", "and", "or", "&&", "||", "=", "&", "|", "!", "{", "(", "[", ":", "=>", "==", "?", ","}
# words of praise or agreement, which get a large positive "!"
PRAISE = {"Perfect", "Excellent", "Great", "great", "Good", "good", "Thanks", "Thank", "passed", "Congratulations",
          "Certainly", "helps", "works", "Yes", "Hello", "Hi", "Wow", "Ah", "successfully", "successful", "done"}
MARKUP = ("<", "#", "/", "\\")


def is_code_context(prev):
    """True if the token before a "!" is an operator, an opening bracket, or nothing (indentation)."""
    return prev == "" or prev in CODE_BEFORE or not prev[-1].isalnum()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    first = len(prefix.token_strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return None, -0.25
    prev = prefix.token_strings[-2].strip()
    if ("!" in s or "！" in s) and "!=" not in s:
        if s.lstrip()[:1] in MARKUP:
            return None, 0.0
        if s.lstrip()[:1] in "([" or is_code_context(prev):
            return None, -6.5
        if prev in PRAISE:
            return None, 3.4
        return None, 1.8
    if s.strip() == "not" and prev in ("if", "If", "when", "When"):
        return None, -5.0
    return None, 0.0

programs.sol:
"""Approximate a few header/boilerplate responses, not general word meaning.

The main positive response is the word 'part' in 'This file is part',
with a weaker response for other 'This ... is part' membership phrases.
Document-initial 'Title:' has a separate, large negative colon response.
Smaller rules recognize source-file declarations and comment headings.
There is also a small alphabetic/numeric document-start calibration.
Only a short text suffix and the document position are retained.
"""
import re

READS = ()

# These declarations can open source files in Python, Java, or JavaScript.
FILE_DECLARATIONS = {'import', 'from', 'package', 'const'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, tail, previous = 0, '', ''
    else:
        _, n, tail, previous = carry
    token = prefix.token_strings[-1]
    text = tail + token
    value = -0.002
    if n == 0:
        word = token.strip()
        if word.isalpha():
            value = -0.05
        elif word.isdigit():
            value = 0.05

    if n == 0 and token.strip() in FILE_DECLARATIONS:
        value = -0.62
    if n == 0 and token == 'Title':
        value = 0.557
    elif n == 1 and previous == 'Title' and token == ':':
        value = -3.006
    elif token == ' part' and re.search(r'\bfile is part$', text):
        value = 0.75 if text.endswith('This file is part') else 0.5
    elif token == ' part' and re.search(r'\bThis(?: \w+)? is part$', text):
        value = 0.10
    elif token == ' once' and text.endswith('#pragma once'):
        value = 0.40
    elif token == ' static' and text.endswith('import static'):
        value = 0.30
    elif token == ' by' and text.endswith('Created by'):
        value = 0.33
    elif token == ' description' and re.search(r'\bFile description$', text):
        value = 0.40

    return (doc, n + 1, text[-80:], token), value

"""A sparse spelling detector centered on the East Asian non- character 非.

Standalone 非 gets a large response, larger with recent Japanese kana;
merged compounds get less. Slavic ne-/nie- and Spanish no are checked at
word starts, with recent word frequencies distinguishing languages.
Portuguese não also gets a small response. Certain splits of ne and Fei
are recognized. Korean bi/mi, Chinese 飞/飛, 微 and 弥/彌, and Vietnamese
Vi/mi get separate lexical responses, not necessarily semantic negation.
Other tokens receive zero. The short text memory resets between documents.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def language(text, choices):
    words = re.findall(r"[^\W\d_]+", text.lower())[-18:]
    if not words:
        return ''
    return max(choices, key=lambda lang: sum(
        min(6.0, zipf_frequency(word, lang)) for word in words))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ''
    else:
        before = carry[1]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    low = text.lower()
    value = 0.0
    start = (raw != raw.lstrip() or not before
             or not before[-1].isalpha())
    if text == '非':
        japanese = re.search(r'[\p{Hiragana}\p{Katakana}]', before)
        value = 6.8 if japanese else 5.4
    elif '非' in text:
        value = 3.0 if text == '并非' else 0.65
    elif text in ('飞', '飛'):
        value = 1.9 if text == '飞' else 2.3
    elif low == 'не' and start:
        value = 1.27
    elif low.startswith('не') and len(low) == 3 and start:
        value = 0.75
    elif low.startswith('е') and re.search(r'(?:^|\W)н$', before.lower()):
        value = 1.25
    elif low.startswith('ne') and len(low) <= 3 and start:
        guess = language(before, ('cs', 'sk', 'fr', 'de', 'en', 'it', 'tr'))
        if guess in ('cs', 'sk'):
            value = 1.2
    elif (low == 'nie' and start) or (low.startswith('ie')
            and re.search(r'(?:^|\W)n$', before.lower())):
        if language(before, ('pl', 'de', 'en')) == 'pl':
            value = 1.35
    elif low == 'no' and start:
        if language(before, ('es', 'en', 'it', 'pt')) == 'es':
            value = 0.68
    elif low == 'não':
        value = 0.45
    elif text == '비':
        value = 5.7 if start else 2.8
    elif text == '미':
        value = 1.7 if start else 1.35
    elif text == '微':
        value = 1.2
    elif text in ('弥', '彌'):
        value = 0.8
    elif text == 'Vi' or low == 'mi':
        if language(before, ('vi', 'en', 'it', 'fr', 'es', 'de')) == 'vi':
            value = 3.3 if text == 'Vi' else 1.5
    elif low == 'i' and raw == text and before.lower().endswith('fe'):
        value = 1.8 if text == 'I' else 5.5
    return (doc, (before + raw)[-320:]), value

"""Local quantity-word and l/e-spelling responses, not general smallness.

Lowercase ' little' is strong but reduced after an indefinite article or
certain modifiers. ' much' is largest after negation-like contexts. Middle
and some split little/middle stems get fixed positive values. Short le and
e-l fragments depend on the preceding letters: usually negative after e,
positive after d/t/k/p, and weaker for extended fragments. Katakana re is
negative, especially after an e-syllable. Unmatched tokens get zero.
"""
import unicodedata
from anyascii import anyascii

READS = ()


def unaccent(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def predict(token, previous):
    word = token.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    degree = {'as', 'so', 'too', 'how', 'very', 'rather', 'pretty', 'quite'}
    if lower == 'little':
        if token != ' little':
            return 5.9
        if prev in {'a', 'an'}:
            return 0.05
        if prev in {'very', 'rather', 'pretty', 'quite'}:
            return 1.4
        if prev in degree:
            return 2.6
        if prev in {'the', 'this', 'that', 'these', 'those', 'some'}:
            return 4.1
        return 5.8
    if token == ' much':
        if prev in degree or prev in {'that', 'this', 'thank', 'thanks'}:
            return 0.0
        if prev in {'not', "n't", "'t", 'without', 'no', 'until'}:
            return 6.5 if prev == 'without' else 4.3
        if prev in {'have', 'has', 'had', 'do', 'did', 'get', 'take'}:
            return 2.6
        return 0.8
    if lower == 'middle':
        return 1.3 if word[0].isupper() else 0.7
    if lower.startswith('litt') and len(lower) <= 5:
        return 3.4
    fragment = unaccent(word)
    left = unaccent(previous)[-1:]
    if word == 'レ':
        sound = anyascii(previous[-1:]).lower()
        return -5.5 if sound.endswith('e') else -0.4
    if fragment == 'ittle' and previous.lower().endswith('l'):
        return 6.0
    if fragment == 'iddle' and previous.lower().endswith('m'):
        return 1.3
    if word == token and fragment == 'itt' and left == 'l':
        return 3.5
    if len(fragment) <= 4 and fragment.endswith('ele'):
        return -1.8
    if word == token and len(fragment) <= 3 and fragment.startswith('e'):
        if unaccent(previous).endswith('el'):
            return -1.6
        if prev.endswith(('itt', 'idd')):
            return 2.8
    if word == token and fragment.startswith('le') and len(fragment) <= 3:
        if fragment == 'let' and prev.endswith('idd'):
            return 7.6
        if left == 'e':
            value = -3.8
        elif left in {'d', 't', 'k', 'p'}:
            value = 2.8
        elif left in {'l', 'a', 'i', 'o', 'u', 'y'}:
            value = -0.2
        elif left.isalpha():
            value = 0.2
        else:
            value = 0.0
        if previous and previous[-1:].lower() in 'äöüő':
            value = -2.1
        if fragment != 'le':
            value *= 0.5 if fragment == 'let' else 0.2
        return value
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, float(predict(prefix.token_strings[-1], previous))

programs.haiku:
"""Layer-1 MLP down-projection, hidden unit 1942.

What it responds to, in plain terms:

1. The quantifier "little" and "much" when they mean "a small amount / not much"
   of something: "had little experience", "pay little attention", "my little toy",
   "not much", "have much of an impact". For "little" it is strong (about 5),
   a bit weaker after a degree word ("very little", "how little", "so little":
   about 2), and zero for "a little". For "much" it is strong after a negation or
   verb such as "not", "no", "have", "pay" (about 4), weak otherwise ("is much",
   about 1), and zero after "so", "too", "very", "how", "pretty", "as" ("so much",
   "how much", "pretty much").
2. The English syllable "le" written as a word piece (also "let", "lec").
   After a word ending in the letter "e" (Gene|lec, Ade|le, pe|le|chuco) it is
   negative (about -2.5); after a word ending in t, d, k or p (-tle, -dle, -kle,
   -ple: Ward|le, tick|le, ap|ple) it is positive (about 1.5). Everything else is 0.

Predictions are these fixed values; the program has no other state.
"""

READS = ()

LITTLE = {"little", "Little"}
MUCH_HIGH_AFTER = {"not", "no", "Not", "have", "has", "had", "pay", "provide"}
MUCH_LOW_AFTER = {"so", "too", "very", "how", "How", "Very", "pretty", "as"}
LE_PIECES = {"le", "let", "lec", "lest", "lett", "LE"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]  # raw, e.g. " little" or "le"
    word = token.strip()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    value = 0.0
    if word in LITTLE:
        if before in ("a", "A"):
            value = 0.0
        elif before in MUCH_LOW_AFTER:
            value = 2.0
        else:
            value = 5.0
    elif word == "much":
        if before in MUCH_HIGH_AFTER:
            value = 4.0
        elif before not in MUCH_LOW_AFTER:
            value = 1.0
    elif token in LE_PIECES and same_doc:
        if before.endswith("e"):
            value = -2.5
        elif before[-1:] in ("t", "d", "k", "p"):
            value = 1.5
    return carry, value

programs.sol:
"""Mostly a spelling-fragment detector: strong positive values for oon/eon,
especially syllables completed across a token boundary. Whole words such as
moon, spoon and soon also respond; 'as soon' suppresses the soon response.
Neu/eu and ei continuations go negative. The small remaining rules approximate
teen/young words, an initial Title: label, and repeated middle-dot leaders.
Unrecognized tokens get zero, leaving many small lexical effects unmodeled.
"""
import re

READS = ()


def response(s, previous, position):
    w, p = s.lower().strip(), previous.lower()
    if position == 1 and previous == 'Title' and s == ':':
        return -11.09
    if s and set(s) == {'·'} and previous and set(previous) == {'·'}:
        return -1.396

    # Familiar words containing the same syllables.
    if w == 'soon':
        if p.strip() == 'as':
            return -0.26
        if p.strip() in {'coming', 'come'}:
            return 9.6
        return 8.1 if p.strip() == 'and' else 5.2
    if w == 'sooner':
        return 2.6
    if re.fullmatch(r'(moon|spoon|boon)s?', w):
        return 4.4
    if w == 'noon':
        return 2.6
    if re.fullmatch(r'cartoons?', w):
        return 1.4
    if re.fullmatch(r'teaspoons?', w):
        return 1.4

    # A continuation token is much more responsive than a long whole word.
    if not s[:1].isspace():
        if re.fullmatch(r'oons?', w):
            return 6.2
        if re.fullmatch(r'[a-z]{1,2}oons?', w):
            return 0.65 if w == 'loon' and p.strip() == 'bal' else 3.0
        if w == 'eon':
            return 6.4
        # Mixed-case On/Only often starts a new code identifier instead.
        if s[:1].islower() or s.isupper():
            if p.endswith(('o', 'e', 'é')) and w.startswith('on'):
                short = bool(re.fullmatch(r'ons?', w))
                if short or w in {'ont', 'oner', 'oney', 'ong'}:
                    if p.endswith('o'):
                        return 7.3 if short else 4.5
                    if p.endswith('é'):
                        return 3.6
                    return 3.5 if short else 4.4
            if p.endswith('o') and re.fullmatch(r'oms?', w):
                return 1.0
            if p.endswith('e') and w.startswith('u'):
                if w in {'ub', 'ube', 'ust'}:
                    return -6.0 if p.endswith('ne') else -3.2
                if w in {'u', 'ur', 'uro', 'up', 'uf'}:
                    return -0.6
            if p.endswith('e') and w in {'in', 'ing'}:
                return -0.4 if w == 'in' else -3.0

    if re.fullmatch(r'[a-z]{1,3}eons?', w):
        return 1.3
    if w in {'neu', 'neuro', 'neur'}:
        return -2.5 if w == 'neu' else -1.7
    if w == 'teen':
        return 2.8 if s[:1].isspace() else 0.8
    if w in {'teens', 'teenage'}:
        return 0.7
    return 0.38 if w == 'young' else 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    return (doc, s, position + 1), response(s, previous, position)

"""A small orthographic 'ag' detector.

Short fragments beginning with 'ag', and an 'a' followed by a separately
encoded 'g', give negative outputs. The effect continues into short word
endings. Longer words and occurrences buried inside a token are weaker.
Transliteration extends the rule to non-Latin writing, with stronger
responses for Arabic alif-ghain and Greek alpha-gamma sequences.
Repeated centered dots are a separate small positive response.
This approximates spelling sensitivity, not the full contextual variation.
"""
from anyascii import anyascii
from functools import lru_cache
import unicodedata

READS = ()


@lru_cache(maxsize=16384)
def spelling(text):
    # Alif is a vowel carrier (omitted by default transliteration).
    # Ghain is the g-like consonant in Arabic renderings of names.
    text = text.translate(str.maketrans({
        'ا': 'a', 'أ': 'a', 'إ': 'a', 'آ': 'a', 'غ': 'g',
    }))
    return anyascii(text).lower()


def predict(text, previous):
    s, p = spelling(text), spelling(previous)
    word = s.strip()
    n = len(word)
    spaced = s[:1].isspace()
    at = word.find('ag')
    if word.startswith('ag'):
        if n > 4:
            return -0.15
        if 'غ' in text:
            return -4.0
        if word.startswith('age'):
            if spaced:
                return 0.10
            return -1.70 if p.endswith('h') else -0.58
        if spaced:
            return -1.16
        if word.startswith('ago'):
            return -2.67
        # Less usual continuations of the spelling 'ag'.
        if word[2:3] in ('h', 't', 'u', 'y'):
            return -3.2
        return -2.44 if p.endswith('h') else -1.49

    # Carry the spelling response into the following word fragment.
    if p.endswith('ag') and s[:1].isalpha():
        vowel = word[:1] in 'aeiou'
        if n > 2:
            return -0.72 if vowel else -0.23
        if word.startswith('g'):
            return -2.40
        if vowel:
            return -2.65 if n == 1 else -1.36
        return -0.84

    if text and set(text) == {'·'}:
        return 0.92 if len(text) >= 2 else 0.0

    if word.startswith('g') and p.rstrip().endswith('a'):
        if n == 1:
            if not spaced and text in ('γ', 'Γ'):
                return -6.0
            return -0.71 if spaced else -4.30
        if spaced:
            return 0.0
        names = ' '.join(unicodedata.name(c, '') for c in text)
        if 'HANGUL' in names or 'CJK' in names:
            return -0.27
        return -2.20 if text.isascii() else -0.90

    if at >= 0 and at + 2 == n:
        return -0.54 if at == 1 else -0.19
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    text = prefix.token_strings[-1]
    return (doc, text), float(predict(text, previous))

programs.haiku:
"""layers.1.mlp.down_proj:1948 -- an "idiomatic prepositional phrase" detector.

In plain terms: the component fires on the word right after a preposition when that word
starts or completes a fixed phrase, as in "in ORDER (to)", "in TERMS (of)", "by MEANS (of)",
"with REGARD (to)", "in ADDITION", "in ACCORDANCE (with)", "in VIEW", "in CASE", "on the
BASIS (of)"; after "as" it fires on "as WELL (as)", "as LONG", "as SOON"; after "a" on quantity
phrases "a LOT", "a FEW", "a BIT", "a LITTLE", "a COUPLE". It fires more weakly on the article
that opens a prepositional phrase, "in THE", "at THE", "on THE", "in A", and more strongly when
that phrase opens a sentence or clause (after a comma, bracket, or full stop). Everywhere else
it predicts about 0.

It reads only the current token and the two before it, so it is a lexical rule and does not
model the context further. Its variance explained is about a third; the rest is small, diffuse
activity that no short rule describes.
"""

READS = ()

# How strongly each preposition opens a phrase whose next word is an article.
PREP_ARTICLE = {"in": 1.3, "at": 1.5, "on": 1.1, "during": 0.9, "under": 1.0, "over": 0.9,
                "within": 0.6, "through": 0.5, "for": 0.5, "with": 0.5, "from": 0.5,
                "into": 0.5, "by": 0.3, "to": 0.3}

# Nouns that complete a fixed phrase after a preposition ("in order", "by means").
PHRASE_HEAD = {"order", "terms", "means", "regard", "regards", "respect", "opposed",
               "addition", "accordance"}
# Weaker fixed-phrase nouns: "in view", "in case", "in line", "in front", "on the basis".
PHRASE_NOUN = {"view", "case", "line", "front", "place", "response", "detail", "charge",
               "basis", "contrast", "sake", "midst"}

AS_WORDS = {"well", "long", "soon", "far", "follows"}
A_WORDS = {"lot", "few", "bit", "little", "couple"}

# Tokens that open a clause or a bracket.
CLAUSE_OPENERS = {",", ".", ";", ":", "(", '"'}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if before == "as" and word in AS_WORDS:
        return carry, 2.0
    if before == "a" and word in A_WORDS:
        return carry, 1.4
    if before in PREP_ARTICLE:
        if word in PHRASE_HEAD:
            return carry, 3.0
        if word in PHRASE_NOUN:
            return carry, 1.5
        if word in ("the", "a", "an"):
            before2 = prefix.token_strings[-3].strip() if len(prefix) > 2 else ""
            opener = before2 == "" or before2 in CLAUSE_OPENERS
            return carry, PREP_ARTICLE[before] * (1.5 if opener else 1.0)
    return carry, 0.0

programs.sol:
"""A sparse approximation using document openings and metadata labels.

At a document's first token, alphabetic fragments tend negative, with
separate rules for Cyrillic, articles, code comments and Markdown headings.
An initial uninterrupted run of middle dots or carets is strongly negative.
Elsewhere, adjacent pieces completing 'Challenge Level', 'Video Transcript'
or 'Popularity' receive negative responses.
Everything else is zero; most token-specific variation remains unexplained.
"""
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    decoration = '' if first else carry[2]
    if first and len(token) >= 2 and len(set(token)) == 1:
        decoration = token[0]
    elif not token or any(ch != decoration for ch in token):
        decoration = ''

    value = 0.0
    if first:
        if token[:1].isalpha():
            value = -0.20
        if regex.fullmatch(r'\p{Script=Cyrillic}+', word):
            value = -0.42
        if word.lower() in {'a', 'an'}:
            value = 0.28 + 0.10 * token.startswith(' ')
        elif word.lower() == 'the':
            value = 0.10 if token.startswith(' ') else -0.13
        if token.startswith(('//', '/*')):
            value = 0.55
        elif token.startswith('#!'):
            value = 0.82
        elif word and not word.strip('#'):
            value = 0.18 if len(word) == 1 else -0.83
        elif token == '<|im_start|>':
            value = 0.079

    if token == ' Level' and previous == ' Challenge':
        value = -0.36
    elif token == ' Transcript' and previous == ' Video':
        value = -0.80
    elif token == 'ularity' and previous == ' Pop':
        value = -0.14
    if decoration == '·':
        value = -1.71
    elif decoration == '^':
        value = -1.97
    return (doc, token, decoration), value

