FRENCH = {
    'mon': 2.8, 'ma': 1.7, 'mes': 1.3, 'ton': 2.0, 'ta': 1.0,
    'tes': 1.5, 'son': 3.0, 'sa': 2.5, 'ses': 2.5, 'notre': 2.3,
    'nos': 1.5, 'votre': 2.1, 'vos': 1.5, 'leur': 2.4, 'leurs': 1.95,
