SPANISH = {
    'mi': 2.7, 'mis': 1.5, 'tu': 2.7, 'tus': 2.3, 'su': 3.2,
    'sus': 2.4, 'nuestro': 1.6, 'nuestra': 1.7,
    'nuestros': 1.1, 'nuestras': 1.1, 'vuestro': 1.3, 'vuestra': 1.3,
