PORTUGUESE = {
    'meu': 1.5, 'meus': 1.2, 'minha': 1.2, 'minhas': 1.1,
    'seu': 1.4, 'seus': 1.5, 'sua': 1.55, 'suas': 1.6,
    'nosso': 1.0, 'nossa': 1.0, 'nossos': 1.0, 'nossas': 1.0,
}
ITALIAN = {
    'mio': 1.0, 'mia': 1.3, 'miei': 1.0, 'mie': 1.0,
    'tuo': 1.3, 'tua': 1.4, 'tuoi': 1.3, 'tue': 1.3,
    'suo': 2.2, 'suoi': 2.1, 'sue': 1.8,
    'nostro': 1.05, 'nostra': 1.05, 'nostri': 1.0, 'nostre': 1.0,
    'vostro': 1.0, 'vostra': 1.0, 'loro': .85,
}

ACTION_VERBS = set('''
    make made making get got getting keep kept keeping put putting
