                    value -= .3
                if before in {'have', 'has', 'had', 'having'}:
                    value += .8
                elif before in {'all', 'both'}:
                    value += .4
                elif before in ACTION_VERBS or before in {'up', 'out', 'off'}:
                    value += .4
                elif before in {'for', 'from', 'at'}:
