programs.haiku:
"""Possessive determiners: the word that introduces 'whose' noun comes next.

The component is silent on almost every token. It fires on a possessive determiner
(his, her, their, its, my, our, your, and the French ses/mes and Russian его/своим) at
roughly the strength listed below, and on the 'me' of 'Let me ...' (as in 'Let me think').
Its size is set by the word alone; it does not depend on earlier tokens, so the program
looks only at the current word and the one before it.
"""

READS = ()

POSSESSIVE = {
    "her": 1.3, "their": 1.2, "his": 1.1, "its": 0.9, "my": 0.8, "our": 0.8,
    "your": 0.6, "ses": 1.5, "mes": 1.5, "его": 1.0, "своим": 1.0,
}
LET_ME = 0.6  # 'me' right after 'let'


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "me" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() == "let":
            return carry, LET_ME
        return carry, 0.0
    return carry, POSSESSIVE.get(word, 0.0)

programs.sol:
"""Approximate a sparse, mixed-sign family of local phrase completions.

Recency and likelihood words respond negatively after English degree words.
CJK size prefixes respond positively before colors, length and some nouns,
with negative rules for lexicalized terms such as writing case and intestines.
A few newness/ownership compounds and document-initial 'Title:' are separate
cues. Most tokens receive 0.002; many rare lexical responses are not modeled.
Only four previous tokens are retained, resetting at each document boundary.
"""
import regex

READS = ()


def english(history, word, age):
    previous = history[-1].strip().lower() if history else ''
    current = word.strip().lower()
    if current in ('recent', 'recently'):
        adverb = current == 'recently'
        if previous == 'most':
            return -2.7 if adverb else -3.1
        if previous in ('more', 'very', 'just', 'relatively'):
            return {
                'more': -1.35 if adverb else -0.85,
                'very': -1.45 if adverb else -1.05,
                'just': -1.1,
                'relatively': -0.45,
            }[previous]
        if any(t.strip().lower() == 'most' for t in history[-4:]):
            return -1.35
        if adverb and previous in ('has', 'have', 'only', "'ve", '’ve'):
            return -0.45
    if previous == 'most' and current == 'of':
        return 0.2
    if current == 'the' and previous == 'of' and len(history) > 1:
        if history[-2].strip().lower() == 'most':
            return 0.18
    if current == 'likely':
        if previous == 'most':
            return -0.95
        if previous == 'more':
            return -0.2
    if current in ('updated', 'modified') and previous == 'last':
        value = -1.4 if current == 'modified' else -1.3
        if history[-1] == 'Last':
            value = -1.5 if current == 'modified' else -2.7
        return value
    if current.lstrip('-') == 'income':
        return {'middle': 2.0, 'high': 1.65, 'low': 0.85}.get(previous, 0.0)
    if previous == 'little':
        return {'thing': 0.8, 'wonder': -1.0}.get(current, 0.0)
    if previous == 'common' and current == 'stock':
        return -1.2
    if previous == 'tiny' and current == 'int':
        return -0.75
    if age == 1 and history[-1] == 'Title' and word == ':':
        return -3.69
    return 0.002


COLORS = set('白黑红紅金青蓝藍紫黄黃绿綠粉灰')
BODY_PARTS = set('头頭脚腳手眼脸臉胸腿口身')


def size_compound(previous, word):
    if not previous or not word:
        return 0.0
    modifier = previous[-1]
    first = word[0]
    if modifier == '新' and word in ('陈', '陳'):
        return -4.7  # 新陈代谢: metabolism (literally, new replacing old)
    if modifier == '新' and word in ('鲜', '鮮', '规', '規', '卒'):
        return -2.0  # fresh, new regulations, new graduate
    if modifier == '微' and word in ('调', '調', '笑', '波'):
        return -1.7  # fine adjustment, faint smile, microwaves
    if previous.endswith('所有') and word in ('者', '制'):
        return -2.8  # ownership terms
    if modifier not in '大中小':
        return 0.0
    if modifier in '大小' and word in ('写', '寫', '写的', '寫的', '文字'):
        return -3.0  # uppercase/lowercase writing
    if modifier in '大小' and word in ('肠', '腸'):
        return -2.8  # large/small intestine
    if modifier in '大小' and word in ('额', '額'):
        return -1.5  # monetary amount
    if modifier == '中' and word in ('止', '断', '斷'):
        return -2.6  # stopping/interruption
    # These are lexicalized compounds, not literal descriptions of size.
    if word in ('学', '學', '学位', '學位'):
        return -2.3  # school/degree terms
    if modifier == '中':
        if first in '性':
            return -2.4  # neutrality
        if first in '间間':
            return -1.8  # 'middle'
        if first in '兴興':
            return -1.5  # revival, also a company name
    if modifier == '大' and first in '田陈陳':
        return -2.7  # place/name compounds
    if modifier == '小' and first == '波':
        return -2.5  # wavelets
    if word in ('长', '長'):
        return 2.9
    if word in COLORS:
        return 2.0
    if word in ('脚', '腳'):
        return 2.8
    if word in BODY_PARTS:
        return 0.8
    if word in ('鬼', '神', '魔'):
        return 1.5  # ghosts, gods, demons
    if word == '可爱':
        return 3.5  # 'little cutie'
    # Only Han-script completions belong to this family.
    if regex.fullmatch(r'\p{Script=Han}', first):
        return 0.2 if len(word) == 1 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history, age = (), 0
    else:
        _, history, age = carry
    word = prefix.token_strings[-1]
    value = english(history, word, age)
    if history:
        previous, current = history[-1], word
        if '\ufffd' in previous or '\ufffd' in word:
            # Reassemble characters split across byte-level tokens.
            earlier = b''.join(prefix.token_bytes[-min(age + 1, 4):-1])
            previous = earlier.decode('utf-8', 'ignore')
            completed = (earlier + prefix.token_bytes[-1]).decode(
                'utf-8', 'ignore'
            )
            if '\ufffd' in word:
                current = completed[len(previous):]
        value += size_compound(previous, current)
    return (document, (*history[-3:], word), age + 1), float(value)

programs.haiku:
"""Hamza word pieces in Arabic script (layers.1.mlp.down_proj:1953), version 6.

What it does, in plain terms:
- An Arabic word piece carrying a hamza seat (أ ؤ ئ ء) fires. Glued onto the previous piece
  (no space before it) it fires more (4) than when it opens a word (2.5). The alef forms إ آ
  fire weakly (1.6 glued, 1.0 opening a word).
- The piece right after such a hamza piece, in the same word, keeps firing: 2.5 after
  أ ؤ ئ ء, 0.7 after إ آ. The piece after that fires a little (0.7 and 0.2). Then nothing.
- The colon of a "Title:" header that opens a new document (right after <|endoftext|>)
  fires very strongly (10.9).
Values are rounded group means measured on training text; everything else predicts 0.
"""

READS = ()

STRONG_HAMZA = set("أؤئء")
WEAK_HAMZA = set("إآ")
ARABIC = set(chr(c) for c in range(0x0600, 0x0700))


def is_arabic(s):
    return any(ch in ARABIC for ch in s)


def step(carry, prefix, upstream):
    # carry: the values owed to the next two glued pieces of the current word, or (0, 0)
    s = prefix.token_strings[-1]
    n = len(prefix.document_ids)
    new_doc = n < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        carry = (0.0, 0.0)
    if n >= 3 and s == ":" and prefix.token_strings[-2] == "Title" and prefix.token_strings[-3] == "<|endoftext|>":
        return (0.0, 0.0), 10.9
    if not is_arabic(s):
        return (0.0, 0.0), 0.0
    glued = not s.startswith(" ") and not new_doc
    if any(ch in STRONG_HAMZA for ch in s):
        return (2.5, 0.7), (4.0 if glued else 2.5)
    if any(ch in WEAK_HAMZA for ch in s):
        return (0.7, 0.2), (1.6 if glued else 1.0)
    if glued:
        return (carry[1], 0.0), carry[0]
    return (0.0, 0.0), 0.0

programs.sol:
"""Approximate document-opening responses from simple token shapes.

The response is concentrated at the start of a document (including a run of
identical opening tokens).  Character shape explains much of its large positive
response: short capital abbreviations, zeroes, and line breaks or a single tab.
Longer words tend negative; word frequency separates short words from fragments.
The constants are averages of training activations, not exact lexical responses.
After the opening, predict zero, except at the numerical prefixes 12 and 122.
Word-specific offsets and later contextual fluctuations are not reproduced.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Calibrated responses to the ten ordinary decimal digits at document opening.
DIGITS = (4.965, 0.159, 0.751, -0.337, -0.273,
          -0.114, -0.736, -0.728, 0.070, -0.519)


@lru_cache(maxsize=8192)
def opening(s):
    if len(s) == 1 and '0' <= s <= '9':
        return DIGITS[int(s)]
    if s == '<|endoftext|>':
        return 6.83
    if s.isspace():
        if s == '\t':
            return 4.36
        if '\n' in s:
            if s == '\n':
                return 2.96
            if s == '\r\n':
                return 4.95
            if s.startswith('\t'):
                return 3.65
            return 2.2
        if s == '\u00a0':
            return 1.63
        if s == ' ':
            return 0.297
        if s == '  ':
            return 0.069
        return -0.4
    w = s.strip()
    if w.isascii() and w.isalpha() and w.isupper():
        if len(w) == 2:
            return 10.0 if w[0] == w[1] else (4.65 if s.startswith(' ') else 5.4)
        if len(w) == 3:
            return 2.85
        if len(w) == 4:
            return 1.45
    if s == '**':  # Opening Markdown bold marker.
        return 8.23
    if s.startswith('#include'):
        return 2.76
    if w.isascii() and w.isalpha():
        spaced = s.startswith(' ')
        n = len(w)
        if w.isupper() and n > 4:
            return 0.5
        if n >= 4:
            if w.istitle():
                return -0.4 if n == 4 else -0.8
            if spaced:
                return -0.1 if n <= 5 else -0.35
            return -0.65 if n == 4 else -1.0
        frequency = zipf_frequency(w.lower(), 'en')
        if w.istitle() and not w.isupper():
            if frequency < 3:
                return 1.4
            return 0.85 if frequency < 4.5 else -0.2
        if not spaced and w.islower():
            return -0.7 if n == 1 or frequency > 4.5 else -0.2
        if spaced and frequency > 7.4:
            return 0.42
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = opening(s)
        return (doc, token, True, value, '1' if s == '1' else ''), value
    _, first, repeating, initial, number = carry
    repeating = repeating and token == first
    number = number + s if number else ''
    if number not in ('1', '12', '122'):
        number = ''
    value = initial if repeating else 0.0
    if number == '12':
        value = 2.03
    elif number == '122':
        value = 1.34
    return (doc, first, repeating, initial, number), value

"""Approximate two responses: English evidential grammar and a spelling effect.

'Appears/seems to', attributed 'to be/have', and 'as if/though' are strongly
negative; possibility modals and probability adverbs are weaker cues. Ordinary
infinitives stay near zero. A small negative also marks short word-continuation
pieces completing a vowel/labial/l sequence (abl, apel, etc.), including
unvowelled Arabic spellings. Other lexical cross-responses are left out.
"""
import re
from functools import lru_cache
from anyascii import anyascii
import regex
import wordnet

READS = ()
SEEM = {'seem', 'appear'}
REPORT = {'say', 'believe', 'consider', 'allege'}
JUDGE = {'think', 'claim', 'deem', 'presume', 'estimate', 'assume',
         'perceive', 'speculate'}
EVIDENCE = {'find', 'report', 'show', 'prove', 'confirm', 'observe',
            'discover', 'see', 'judge', 'infer', 'demonstrate', 'identify'}
WEAK = {'suppose', 'predict', 'project', 'expect', 'pretend', 'happen'}
MODIFIERS = set('not never also already still well really actually even '
                'generally usually often only always indeed'.split())
ADVERBS = {'apparently': -3.8, 'seemingly': -4.3, 'presumably': -4.0,
           'supposedly': -4.0, 'allegedly': -2.1, 'reportedly': -1.8,
           'evidently': -1.0, 'possibly': -1.0, 'probably': -0.7,
           'perhaps': -0.25}
# Coefficients for the two base-form auxiliaries after each modal.
MODALS = {'may': (-1.1, -1.7), 'might': (-1.1, -1.7),
          'could': (-0.7, -0.85), 'must': (-0.23, -0.57), 'can': (-0.13, 0.0)}


@lru_cache(maxsize=2048)
def verbs(word):
    return set(wordnet.base_forms(word, 'verb')) | {word}


def strength(word):
    """Predictions on 'to', then 'be', then 'have', after this cue."""
    v = verbs(word)
    if v & SEEM:
        return (-4.4 if word.endswith(('ed', 'ing')) else -5.7, -6.2, -6.2)
    if v & REPORT:
        return -2.5, -6.2, -6.2
    if v & JUDGE:
        return -2.5, -4.5, -4.5
    if v & EVIDENCE and word != 'report':  # Bare 'report' is often a noun.
        return -0.7, -5.5, -3.9
    if v & WEAK:
        return -0.5, -1.5, -1.5
    if word == 'likely':
        return 0.0, -1.1, -1.1
    if 'know' in v:
        return 0.0, -3.6, -3.6
    if word == 'out':  # 'turned out to be'.
        return 0.0, -2.5, -2.5
    return 0.0, 0.0, 0.0


def trim(words):
    while words and words[-1] in MODIFIERS:
        words.pop()
    return words


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if not token:
        return (doc, history), 0.0
    text = history + token
    match = re.search(r'[A-Za-z]+$', text)
    word = match[0].lower() if match else ''
    value = ADVERBS.get(word, 0.0)
    if word in {'to', 'be', 'have', 'if', 'though', 'being', 'having',
                'may', 'might', 'likely'}:
        past = re.split(r'[,.!?;]|\n\s*\n', text[:match.start()].lower())[-1]
        words = re.findall(r'[a-z]+', past)
        last = words[-1] if words else ''
        clean = trim(words.copy())
        head = clean[-1] if clean else ''
        if word == 'to':
            value = -0.9 if last == 'as' else strength(head)[0]
        elif word in ('be', 'have'):
            be, have = MODALS.get(head, (0.0, 0.0))
            if head == 'to':
                before = trim(clean[:-1])
                _, be, have = strength(before[-1] if before else '')
            value = be if word == 'be' else have
            if head in ('may', 'might') and last == 'not':
                value -= 0.25
        elif word in ('if', 'though') and last == 'as':
            v = verbs(words[-2]) if len(words) > 1 else set()
            value = -6.3 if v & (SEEM | {'look', 'sound', 'feel'}) else -3.7
        elif word in ('being', 'having') and head == 'as':
            if len(clean) < 2 or clean[-2] not in ('well', 'far', 'much'):
                value = -3.2
        elif word == 'likely':
            value = -0.2 if last in ('more', 'less') else -0.9
        elif word in ('may', 'might'):
            value = 0.15 if last in ('we', 'i') else -0.2
            if match[0] == 'May':
                value = 0.0
    # Only short continuation pieces, not every whole word with these letters.
    piece = anyascii(token).lower()
    if (not value and token[0].isalpha() and history[-1:].isalpha()
            and piece.isalpha() and len(piece) <= 3 and 'l' in piece):
        ending = r'[bmp][aeiouy]?l[aeiouy]{0,2}$'
        if not regex.search(r'\p{Script=Arabic}', token):
            ending = 'a' + ending
        if re.search(ending, anyascii(text[-40:]).lower()):
            value = -0.7
    return (doc, text[-160:]), value

programs.haiku:
"""layers.1.mlp.down_proj:1955: a hedging / raising-construction detector (negative).

The component goes strongly negative on the word that sets up an epistemic or reported
predicate, where the next word is expected to be "be" or "have":

- the infinitive marker after a raising or reporting verb: "seems to", "appears to",
  "is said to", "claims to" (activation about -3 to -6 on " to");
- the verb "be" or "have" after that infinitive: "was found to be", "seems to have",
  "is believed to have" (about -5.5); weaker after "turns out to be", "likely to be" and
  "supposed to be" (about -1.5);
- the verb "be" or "have" after an epistemic modal: "may be", "might be", "could be",
  "may not be", "might have" (about -1);
- hedging adverbs: "apparently", "presumably", "seemingly" (about -4), "possibly", "likely",
  "probably" (about -1, -0.7);
- "as if", "as though", "as being" (about -4).

Everywhere else it predicts 0; its small positive and negative values elsewhere are not
captured by any simple rule.
"""

READS = ()

# Verbs that take a raising infinitive with an epistemic meaning: "seems to".
SEEM = {"seem", "seems", "seemed", "Seems", "appear", "appears", "appeared", "appearing"}
# Verbs and participles that report or assess: "is said to", "is considered to".
REPORTED = {"said", "believed", "presumed", "assumed", "thought", "considered", "claimed",
            "claims", "claim", "deemed", "estimated", "reported", "proven"}
# Everything that can come before an infinitive "to be" / "to have" in a finding or report.
FINDING = SEEM | REPORTED | {"found", "shown", "confirmed", "proved", "prove", "proves",
                             "inferred", "seen", "alleged", "identified"}
# Modals and negators before a bare "be" or "have".
MODAL = {"may": -1.2, "might": -1.0, "could": -0.7, "not": -0.6, "even": -0.7, "also": -0.3}
# Hedging adverbs, on the adverb itself.
ADVERB = {"apparently": -3.8, "Apparently": -3.8, "presumably": -4.0, "seemingly": -4.5,
          "supposedly": -3.8, "probably": -0.7, "Probably": -0.7, "likely": -0.7,
          "possibly": -1.0, "Possibly": -1.0, "perhaps": -0.2, "Perhaps": -0.2}


def step(carry, prefix, upstream):
    toks = [s.strip() for s in prefix.token_strings]
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    v = 0.0
    if cur == "to":
        if prev in SEEM or prev in ("claims", "claim", "deemed"):
            v = -5.5
        elif prev in REPORTED:
            v = -3.0
    elif cur in ("be", "have"):
        if prev == "to":
            if prev2 in FINDING:
                v = -5.5
            elif prev2 in ("out", "likely", "supposed"):
                v = -1.5
            elif cur == "have":
                v = -1.4
            else:
                v = -0.35
        else:
            v = MODAL.get(prev, 0.0)
            if cur == "have" and prev in ("may", "might"):
                v = -1.7
    elif cur in ("if", "though", "being", "having") and prev == "as":
        v = -4.0
    elif cur == "that" and prev in SEEM:
        v = -2.0
    else:
        v = ADVERB.get(cur, 0.0)
    return carry, float(v)

programs.sol:
"""Detect quantity slots: numbers in East Asian prose and after articles.

The strength of an Arabic numeral is set by its introducer and carried over
its digits. Calendar units are strong; intervening punctuation weakens it.
Chinese/Japanese/Korean quantity words and English article-plus-number
constructions also respond, as do two Vietnamese quantity words. Double backslashes
distinguish math rows from string escapes. A separate boundary exception
models the sharp response to a document-initial 12.
"""
import regex
import unicodedata

READS = ()
HAN_END = regex.compile(r'\p{Han}$')
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
EAST_ASIAN = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]')
HANGUL_END = regex.compile(r'\p{Hangul}$')
ARTICLE = regex.compile(r'(?:^|\s)(?:a|an)$', regex.I)
HAN_TEXT = regex.compile(r'[\p{Han}〇]+$')
NUMBER_WORDS = set('one two three four five six seven eight nine ten'.split())
MATH = regex.compile(r'[{}^&$]')


def han_number(text):
    return bool(HAN_TEXT.fullmatch(text)) and all(
        unicodedata.numeric(ch, None) is not None for ch in text
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, 0.0)
    _, previous, tail, run, base = carry
    token = prefix.token_strings[-1]
    # Recover a character completed by a byte-fragment token.
    if '\ufffd' in token:
        same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == doc
        count = 2 if same_doc else 1
        raw = b''.join(prefix.token_bytes[-count:])
        decoded = raw.decode('utf-8', 'ignore')
        if decoded and raw.endswith(decoded[-1].encode('utf-8')):
            token = decoded[-1]
    word = token.strip().lower()
    article = bool(ARTICLE.search(tail.rstrip()))
    value = 0.0
    if token.isdecimal():
        if not run:
            if tail.rstrip().endswith(('年', '년')):
                base = 2.1
            elif tail.rstrip().endswith(('月', '월')):
                base = 1.65
            elif KANA.search(previous):
                base = 1.5
            elif HAN_END.search(previous):
                base = 1.12
            elif HANGUL_END.search(tail.rstrip()):
                base = 1.2
            elif HAN_END.search(tail.rstrip()):
                base = 0.4 if '\n' in previous else 0.8
            elif article:
                base = 0.65
            elif EAST_ASIAN.search(tail[-40:]):
                base = 0.32
            else:
                base = 0.0
            if not token.isascii():
                base = max(base, 1.25)
        if run < 2:
            value = base * (1.05 if run else 1.0)
        else:
            value = base * (0.7 if run < 4 else 0.3)
        if tail == '1' and token == '2':
            value = 4.19
        elif tail == '12':
            value = 1.7
        run += 1
    else:
        run = 0
        if token == ' ' or word in NUMBER_WORDS:
            if article:
                value = 0.65 if token == ' ' else 1.0
            elif token == ' ' and HANGUL_END.search(previous):
                value = 1.2
            elif token == ' ' and previous.strip().lower() in (
                'the', 'his', 'her', 'this', 'that', 'another'
            ):
                value = 0.2
        if han_number(token):
            if token in ('一', '二'):
                value = 0.65
            elif token in ('百', '千'):
                value = 0.35
            elif token in ('万', '亿', '零', '〇'):
                value = 0.1
            else:
                value = 1.15
        elif token.startswith('第') and han_number(token[1:]):
            value = 0.55
        elif token.endswith('一'):
            if token[:-1] in ('的', '了', '另', '每', '那', '最后'):
                value = 0.85
            elif token[:-1] in ('是', '有', '这', '這', '在'):
                value = 0.25
        # Few/how many, two/both, and other short Chinese quantifiers.
        if token in ('几', '幾'):
            value = 2.2 if token == '几' else 1.4
        elif token in ('兩', '两'):
            value = 1.6
        elif token in ('每', '哪', '余', '餘'):
            value = 1.0
        elif token in ('数', '數', '多', '某', '那', '各'):
            japanese_count = token in ('数', '數') and KANA.search(previous)
            value = 1.5 if japanese_count else 0.45
        # Japanese 'every' and 'what/how many'.
        if token == '毎':
            value = 1.25
        if token in ('何', 'なん'):
            value = 1.3 if KANA.search(tail[-40:]) else 0.5
        # Korean one/two/three/four, how many, several.
        if word in ('한', '두', '세', '네', '몇', '여러'):
            value = 1.25
        if word == 'one' and previous.strip().lower() in (
            'which', 'each', 'any', 'every', 'last', 'only'
        ):
            value = -0.3
        # Vietnamese 'one/a' and plural indefinite determiner.
        if word == 'một':
            value = 0.7
        elif word == 'những':
            value = 1.6
        if '\u00a0' in token:
            value = 0.08
        if '\\\\' in token:
            quoted = ('"' in token or "'" in token) or any(
                q in token or q in tail[-40:]
                for q in ('\\"', "\\'"))
            quoted = quoted or any(
                w in tail for w in ('print(', 'printf(', 'console.log(')
            )
            value = -0.8 if quoted else 1.7 if MATH.search(tail) else 0.0
        elif token == 'cr' and previous.endswith('\\'):
            value = 2.3 if MATH.search(tail[:-1]) else 0.0
    return (doc, token, (tail + token)[-120:], run, base), value

"""A sparse spelling-and-punctuation detector.

Negative responses mark single-quoted markup attributes, quotation marks
(especially in Han text), and token breaks inside zh/lh spellings. A few
Chinese writing/court spellings are additional negative cues; 章 after a
number (a chapter label) is exempted. Most tokens get a near-zero value.
State holds only recent text and whether a tag is open;
it is cleared at document boundaries. Initial NUL and whitespace are treated
separately because their response at a fresh context is unusually large.
"""
import regex
import unicodedata

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
MARKUP_ATTRIBUTES = set('''
    width height x y fill stroke stroke-width text-anchor dominant-baseline
    xmlns xmlns:xlink transform viewBox href id name value type nowrap
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, recent, in_tag = '', b'', False
    else:
        _, previous, recent, in_tag = carry
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    context = recent.decode('utf-8', errors='replace')
    han_nearby = bool(HAN.search(context[-10:]))
    value = -0.003

    # Single quotation marks that start an HTML/XML attribute value.
    if s.startswith("='"):
        match = regex.search(r'[\w:-]+$', context)
        attribute = match[0] if match else previous.strip()
        if attribute in {'class', 'src'}:
            value = -5.8
        elif attribute == 'style':
            value = -3.8
        elif in_tag and attribute in MARKUP_ATTRIBUTES:
            value = -2.4
        else:
            value = 0.05
    elif s.strip() == "'>":
        value = -0.85
    elif s.strip() == '‘':
        value = -2.1 if han_nearby else -0.35
    elif s == '’':
        value = -1.05 if han_nearby else (
            -0.9 if previous.endswith('’') else 0.10
        )
    elif s == '『':
        value = -0.47
    elif s == '』':
        value = -0.21
    elif s.strip() == "''":
        value = -0.36
    elif s == " '":
        value = -0.06
    elif s in {'h', 'H', 'hi', 'hy'}:
        ending = previous[-1:]
        short_stem = 1 <= len(previous.strip()) <= 3
        value = 0.06
        if short_stem and ending.lower() == 'z':
            value = -2.5 if s == 'h' else -1.1
        elif short_stem and ending.lower() == 'l':
            proper_name = (len(previous.strip()) == 3
                           and previous.strip().istitle())
            if s == 'h':
                value = -1.6 if proper_name else -0.95
            else:
                value = -0.15
    elif s.endswith('法院'):
        value = -min(2.14, 0.76 + 0.69 * (len(s) - 2))
    elif s.endswith('文章'):
        value = -1.0
    elif s == '章':
        number = previous[-1:]
        ordinal = bool(number) and (
            unicodedata.numeric(number, None) is not None
        )
        value = -0.06 if ordinal else -1.2
    elif s in {'<|im_start|>', '<|im_end|>'}:
        value = -0.057

    if first:
        if s == '\x00':
            value = -10.37
        elif s == '<|im_start|>':
            value = -0.231
        elif s.isspace():
            value = -0.45 if s != ' ' else -0.21
        else:
            value = -0.05

    for ch in s:
        if ch == '<':
            in_tag = True
        elif ch == '>':
            in_tag = False
    carry = (doc, s, (recent + b)[-192:], in_tag)
    return carry, value

programs.haiku:
"""Layer-1 MLP down_proj component 1958: a few word-level rules.

This component is diffuse. Its activation is usually within about ±0.2 and spread over
most tokens, with rare large swings. These rules capture its most consistent pieces and
predict 0 everywhere else:

* the first token of a document or row, which has no left context: a whitespace-only
  token gives about -0.36, a space-led word about -0.10;
* the middle dot "··" (a list separator): about +0.26;
* Chinese words for article, chapter, court and hospital (文章, 篇文章, 章, 法院,
  人民法院, 院, 醫院): strongly negative, about -0.83 (人民法院 is near -2.3);
* Chinese party and politics words (党, 党的, 政治, 党组织): about +0.30;
* the English word " article" / " articles": about +0.23;
* opening CJK quote marks ‘ and 『: about -0.63.

Stateless apart from the document boundary check: each value depends only on the newest
token and whether it starts a document.
"""

READS = ()

MIDDLE_DOT = {"··"}
COURT_ARTICLE_ZH = {"文章", "篇文章", "章", "法院", "人民法院", "院", "醫院"}
PARTY_ZH = {"党", "政治", "党的", "党组织"}
ARTICLE_EN = {" article", " articles"}
OPEN_QUOTE = {"‘", "『"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if token in MIDDLE_DOT:
        value = 0.26
    elif token in COURT_ARTICLE_ZH:
        value = -0.83
    elif token in PARTY_ZH:
        value = 0.30
    elif token in ARTICLE_EN:
        value = 0.23
    elif token in OPEN_QUOTE:
        value = -0.63
    elif first and token.strip() == "":
        value = -0.36
    elif first and token.startswith(" "):
        value = -0.10
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A partial, local spelling model of a should / -oud / -old response.

Most tokens give zero. The modal 'should' is stronger after first-person
subjects and in code-like contexts. Rounded-vowel spellings followed by d/l
fragments are positive; several competing continuations are negative.
Short transliterated sound fragments receive similar corrections. Separate
rules handle repeated middle dots and initial empty code comments.
These are spelling rules, not a shared meaning of all the words involved.
State resets at document boundaries.
"""
import re
import regex
from anyascii import anyascii

READS = ()


def bare_modal(s):
    return s.lstrip(' ./_').lower()


def sound_continuation(current, previous):
    """The same rounded-vowel/d pattern in non-Latin sound spellings."""
    x, q = anyascii(current).lower(), anyascii(previous).lower()
    if (regex.search(r'\p{Script=Katakana}', current)
            and regex.search(r'\p{Script=Katakana}', previous)):
        # Only short sound fragments, not whole words such as "data".
        dental = x in ('de', 'do', 'den') or (x == 'da' and 'ー' in current)
        if dental:
            if q.strip() == 'ru' or ('ー' in previous and q.endswith('ru')):
                return 3.0
            if q.strip() == 'u':
                return 5.0
    elif regex.search(r'\p{Script=Hangul}', current):
        if x in ('deu', 'de', 'deo') and re.fullmatch(r'[bp]?o|u', q.strip()):
            return 2.3
    elif regex.search(r'\p{Script=Cyrillic}', current):
        if x.startswith('d'):
            if q.endswith('ol'):
                return 2.5
            if q.endswith('lyu'):
                return 1.5
    return 0.0


def spelling_value(s, previous, before_previous):
    if not previous and s == '//\n':
        return 5.35
    word = s.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    if lower == 'should' or bare_modal(s) == 'should':
        value = 0.23 + 0.9 * (not s[:1].isspace())
        value += 0.4 * word[0].isupper()
        if prev == 'i':
            value += 2.0
        elif prev == 'we':
            value += 1.0 + 0.6 * previous.strip()[0].isupper()
        elif prev == 'you':
            value += 0.35 + 0.5 * previous.strip()[0].isupper()
        elif prev in ('he', 'she', 'it', 'they'):
            value += 0.05
        if '//' in previous or '✓' in previous or not prev:
            value += 0.5
        return value
    if word in ("'t", '’t') and prev.endswith('shouldn'):
        return 0.7 + 0.9 * (before_previous.strip().lower() == 'i')
    if lower in ('would', 'could'):
        return 0.05 if lower == 'would' else 0.10
    bare = re.sub(r'^[^a-zA-Z]+', '', s).lower()
    if bare in ('cloud', 'clouds', 'loud', 'louder'):
        value = 1.4
        if s[:1].isalpha():
            value += 1.6
        elif not s[:1].isspace():
            value += 0.2
        if any(c.isupper() for c in word):
            value += 0.5 if s[:1].isspace() else -0.3
        return value - 0.5 * bare.endswith(('s', 'er'))
    value = 0.0
    if lower in ('oud', 'ould', 'uld'):
        value = 2.0 if lower == 'oud' else 1.3
    elif lower == 'cold':
        return 0.75
    elif lower == 'shout':
        return 2.7
    elif len(word) > 1 and set(word) == {'·'}:
        return -1.25
    if not s.isascii() and previous:
        value += sound_continuation(s, previous)
    if not s or not s[0].isalpha() or not previous:
        return value
    if not previous[-1].isalpha():
        return value
    x, q = s.lower(), previous.lower()
    rounded = re.search(r'(ou|oo|oy|ow|oh|ol|od|our|oul|o)$', q)
    if prev == 'you' and x != 'd':
        rounded = None
    if rounded:
        ending = rounded[0]
        strong = ending in ('ou', 'ol', 'oh')
        if x.startswith(('d', 'ld', 'ud', 'uld', 'od')):
            value += 0.15
            value += 3.0 * (ending in ('ou', 'oul', 'our'))
            value += 3.3 * (ending == 'ol')
            value += 5.0 * (ending == 'oh')
            value += 0.4 * (ending in ('oy', 'ow'))
            if ending == 'od' and (x == 'd' or x.startswith('dd')):
                value += 2.0
            value += 1.2 * (ending == 'o' and x.startswith('od'))
            value += 3.4 * x.startswith(('ud', 'uld'))
            if x.startswith('ld'):
                value += 1.0
            if strong and x.startswith(('db', 'dd', 'ded', 'ds')):
                value += 3.0
                value += 2.0 * (ending == 'ou' and x.startswith('db'))
        elif x.startswith('l'):
            value += 1.5 * (ending in ('ou', 'oul'))
            value -= 2.5 * x.startswith('lev')
            value -= 1.5 * (ending == 'ol')
        elif ending in ('ou', 'oul', 'our', 'oy'):
            if x.startswith(('f', 'v', 'i', 'e', 'a', 'o', 'u', 'p', 'ss')):
                value -= 0.5
            if x.startswith(('f', 'v', 'ill', 'et')):
                value -= 1.0
            if q.endswith('rou') and x.startswith('en'):
