        value -= 3.5
    if x == 'ou':
        value -= 0.2
        value += 1.8 * q.endswith(('h', 'cl'))
        value += 0.5 * q.endswith('d')
    if x == 'rou':
        value += 4.6 * q.endswith('sh') + q.endswith('sc')
    if x.startswith('oked') and q.endswith('ro'):
        value += 2.2
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous = before_previous = ''
    else:
        _, previous, before_previous = carry
    current = prefix.token_strings[-1]
    value = spelling_value(current, previous, before_previous)
    return (document, current, previous), float(value)

"""Predict an OT-shaped spelling response using word pieces and frequency.

The trigger is 'ot', including transliterations, within the newest piece or
across its boundary with the preceding piece. The response also persists
into the next piece of that word. Short word continuations are strongest;
common complete words and long endings are weaker. Rare 'phot' pieces can
be negative. A separate rule captures the document-initial 'Title:' colon.
These are coarse averages, not a full account of individual word responses.
"""
import codecs
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()

@lru_cache(maxsize=32768)
def frequency(word):
    language = 'ru' if any('а' <= c.lower() <= 'я' for c in word) else 'en'
    return zipf_frequency(word, language)


def estimate(token, spelling, word, continuing, after_ot):
    fragment_frequency = frequency(token.strip())
    if continuing:
        if len(spelling) <= 2:
            if fragment_frequency > 1.97:
                return 1.463 if after_ot else 2.857
            other_script = any(
                c.isalpha() and not any(script in unicodedata.name(c, '')
                    for script in ('LATIN', 'CYRILLIC', 'KATAKANA', 'HIRAGANA'))
                for c in token)
            return 0.516 if other_script else 1.178
        if len(spelling) <= 4:
            return 1.385 if spelling.startswith('ot') else 0.820
        return 0.792 if spelling.startswith('ot') else 0.128

    word_frequency = frequency(word)
    if word_frequency > 4.08:
        if fragment_frequency <= 4.08:
            return -0.104 if word_frequency <= 4.97 else -0.564
        return 0.144 if word_frequency <= 4.41 else 0.040
    ending = len(spelling) - spelling.rfind('ot') - 2 if 'ot' in spelling else 0
    if ending > 1:
        return 0.143 if ending <= 4 else 0.019
    return -0.913 if 'phot' in spelling else 0.534


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, word, position = b'', '', 0
    else:
        _, pending, word, position = carry
    data = pending + prefix.token_bytes[-1]
    token, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    previous_word = word
    spelling, previous = roman(token).strip(), roman(word)
    continuing = bool(token[:1].isalpha() and word)
    split_ot = continuing and previous.endswith('o') and spelling.startswith('t')
    after_ot = continuing and bool(re.search('ott*$', previous))
    if token.isalpha():
        word = (word + token)[-60:]
    elif token:
        last = re.search(r'[^\W\d_]+$', token)
        word = last.group() if last else ''
    value = 0.0
    if 'ot' in spelling or split_ot or after_ot:
        value = estimate(token, spelling, word, continuing, after_ot)
    if position == 1 and previous_word == 'Title' and token == ':':
        value = 10.145
    return (doc, pending, word, position + 1), float(value)

"""Detect introductions to named or descriptive strings in code and structured text.
Quotes after description labels or quoted name keys respond most strongly.
Other string-valued fields and their colons respond less. A short document-local
text tail recognizes snake_case/camelCase labels and a few negative separators.
"""
import re

READS = ()
# Synonymous labels, delimiter response, string-value response.
FIELDS = {
    'description': ('description desc', 2.74, 7.11),
    'help': ('help', 1.71, 2.17),
    'title': ('title heading caption subject', 1.65, 3.73),
    'name': ('name', 0.73, 2.18),
    'label': ('label', 0.73, 4.07),
    'message': ('message msg prompt', 0.69, 2.27),
    'text': ('text content', 0.83, 2.95),
    'command': ('command cmd', 0.02, 1.89),
}
LABELS = {w: group for group, row in FIELDS.items() for w in row[0].split()}
LAST_WORD = re.compile(r'''([A-Za-z_][\w:.-]*)['"`\s:=>(]*$''')
OPEN = re.compile(r'''^(['"]?:[ \t]*|[ \t=,(\[!]+)(['"])''')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = 0.0
    if s.strip().lower() == 'name':
        value = 0.24 if s[:1].isspace() else 0.80
    opening = OPEN.match(s)
    delimiter = s in (':', ':\n', '":', "':", '=', '=f', ' =')
    if opening or delimiter:
        match = LAST_WORD.search(tail)
        cue = match[1] if match else ''
        cue = re.sub(r'([a-z])([A-Z])', r'\1 \2', cue)
        parts = re.findall('[a-z]+', cue.lower())
        group = next((LABELS[p] for p in reversed(parts) if p in LABELS), None)
        # Looking up an existing name is not introducing one.
        if parts and parts[0] in ('get', 'find', 'by', 'is'):
            group = None
        if opening:
            before = opening[1]
            value += (1.03 if ':' in before else 0.58 if '(' in before
                      else 0.79 if '[' in before else 0.25)
            assigned = re.search(r'(?:[:=]>?|=>)\s*$', tail)
            if group and (assigned or any(c in before for c in ':=(')):
                value += FIELDS[group][2]
                if group == 'name':
                    if re.search(r'''['"]\s*:\s*$''', tail) or before[0] in "\"'":
                        value += 3.35
                    if len(parts) > 1:
                        value -= 1.70
        else:
            value += 0.10 if ':' in s else 0.0
            if group:
                value += FIELDS[group][1]
    if s == '/' and re.search(r'\d/\d+$', tail):
        value -= 1.28
    if s in (' of', ' OF'):
        if tail.endswith('DESCRIPTION'):
            value -= 3.78
        elif tail.endswith('Description'):
            value -= 1.50
    return (doc, (tail + s)[-100:]), value

