programs.sol:
"""Approximate a modifier/quantifier-sensitive component.

Chinese 'one + measure' phrases are positive after each, same, some, which,
this, or another; fused tokens have a weaker response. English split
indefinite pronouns have mostly negative responses, while 'of' after
'each/any/which one' or 'no/any amount' is positive. A line-initial '1'
following a newline is negative, especially after a colon. 'Any arbitrary'
also receives a positive response.
Other tokens predict zero, apart from a coarse document-start estimate.
A short byte suffix reconstructs split characters; documents reset the state.
"""
import re

READS = ()
# Common classifier and time-unit heads in Chinese "one ..." phrases.
MEASURES = set(
    '个個位名种種次场場件篇批轮輪步年天月日分秒层層条條'
    '本只支份点點块塊杯碗方起款道户戶辆輛头頭台座套段页頁'
    '册冊番遍回口张張把根门門级級节節'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        raw, previous = b'', ''
    else:
        _, raw, previous = carry
    tail = raw.decode('utf-8', 'replace')
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = tail.rstrip()
    value = 0.0
    if not tail:
        value = -0.04
        if token == '<|im_start|>':
            value = -0.30
        elif word in ('a', 'an', 'the'):
            value = 0.25
        elif len(token) == 1 and token in '0123456789':
            value = 0.15

    modifier = previous.strip()
    # A Han modifier may span several byte-level tokens.
    if '\ufffd' in modifier:
        modifier = before[-1:]
    one_phrase = token.startswith('一') and (
        len(token) == 1 or token[1] in MEASURES
    )
    if one_phrase:
        if modifier == '同':  # Same.
            value = 1.75
        elif modifier in ('任', '任何'):  # Any.
            value = 1.70
        elif modifier in ('每', '某', '哪', '在哪'):  # Each, some, which.
            value = 1.25
        elif modifier in ('另', '又', '单', '單'):  # Another, single.
            value = 0.90
        elif modifier == '其中':
            value = 0.70
        elif modifier in ('这', '這', '那', '此', '这样', '這樣'):
            value = 0.55
        elif modifier in ('上', '下', '前', '后', '後', '新', '最后', '最新'):
            value = 0.40
    elif token.startswith('同一'):
        value = 0.53
    elif token.startswith(('每一', '某一')):
        value = 0.45
    elif token.startswith(('这一', '這一')):
        value = 0.30
    elif token.startswith('另一'):
        value = 0.18

    modifier = modifier.lower()
    if token.strip() == 'one':
        if modifier == 'some':
            value = -0.75
        elif modifier == 'every':
            value = -0.40
        elif modifier == 'no':
            value = -0.26
        elif modifier in ('which', 'any', 'each'):
            value = 0.26
    elif word in ('thing', 'body', 'where'):
        if modifier in ('some', 'any', 'every', 'no'):
            value = -0.80 if word == 'thing' else -0.40
    elif word == 'arbitrary' and modifier == 'any':
        value = 0.65
    elif word == 'of':
        if re.search(r'\b([Aa]ny|[Ee]very|[Ee]ach|[Ww]hich) one$', before):
            value = 0.90
        elif re.search(r'\b([Nn]o|[Aa]ny) amount$', before):
            value = 1.20

    if token == '1' and '\n' in tail:
        indentation = tail.rsplit('\n', 1)[-1]
        if not indentation.strip():
            if indentation:
                value = -0.18 if before.endswith((':', '：')) else -0.02
            elif before.endswith('：'):
                value = -0.85
            elif before.endswith(':'):
                value = -0.40
            else:
                value = -0.25

    raw = (raw + prefix.token_bytes[-1])[-256:]
    previous = token if token.strip() else previous
    return (doc, raw, previous), value

