"""layers.1.mlp.down_proj:1967 — the "one" of "every one / any one / some one".

The component fires on the numeral 一 ("one") when it is used as a quantifier after a
determiner-like word, as in 每一 (every one), 任一 (any one), 某一 (some one),
哪一 (which one), 同一 (the same one). The strongest case is 任 + 一, then 某, 每.
English analogues: the "of" after "each/every/any one" and after "no amount".
The first token of each document gets the average value there (-0.05; its sign varies).
Everywhere else the prediction is 0 (the component is nearly silent on ordinary text).
"""
from collections.abc import Mapping

READS = ()

# Chinese word before the numeral 一 -> activation on that 一
DETERMINER = {"任": 1.7, "哪": 1.5, "某": 1.4, "每": 1.15, "同": 1.0,
              "其中": 0.8, "这": 0.45, "這": 0.45, "另": 0.3, "上": 0.3}
# First token of a document (right after <|endoftext|>): a weak, mixed-sign signal
DOC_START = -0.05

# English: "of" after "one" that follows each/every/any/another
ONE_QUANTIFIERS = {"each", "every", "any", "another"}


def step(carry, prefix, upstream: Mapping):
    toks = prefix.token_strings
    docs = prefix.document_ids

    def tok(back):
        i = len(toks) - 1 - back
        if i < 0 or docs[i] != docs[-1]:
            return ""
        return toks[i].strip()

    cur, prev, prev2 = tok(0), tok(1), tok(2)
    value = 0.0
    if len(toks) == 1 or docs[-2] != docs[-1]:
        value = DOC_START                              # first token of a document
    elif cur.startswith("一") and prev in DETERMINER:
        value = DETERMINER[prev]                       # 每 + 一个 -> the 一
    elif len(cur) >= 2 and cur[0] in DETERMINER and cur[1] == "一":
        value = 0.5                                    # 每一 written as one token
    elif cur == "of" and prev == "one" and prev2.lower() in ONE_QUANTIFIERS:
        value = 0.8                                    # each one [of]
    elif cur == "of" and prev == "amount" and prev2 == "no":
        value = 1.2                                    # no amount [of]
    return carry, float(value)

