"""A colon-punctuation detector.

Plain and fullwidth colons are strong; fused quotes, double colons and
line endings weaken the signal. Digits and file names before a plain
colon strengthen it.
An identifier used as an indented object key weakens the signal.
Repeated middle dots have negative sign. A document beginning with the
heading ``Title:`` has a separate, sharp negative spike.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos = carry[1] + 1 if carry and carry[0] == doc else 0
    carry = (doc, pos)
    s = prefix.token_strings[-1]
    t = s.strip()
    if pos == 0 and s == 'Title':
        return carry, -2.5
    if pos == 1 and s == ':' and prefix.token_strings[-2] == 'Title':
        return carry, -15.38
    if t and all(c == '·' for c in t) and len(t) >= 2:
        return carry, -1.6
    if ':' not in s and '：' not in s:
        return carry, 0.0
    if pos == 0:
        return carry, 0.0
    if '://' in s:
        value = 0.0
    elif '::' in s or ':=' in s:
        value = 0.68
    elif t == ':)':
        value = (0.63 if s.startswith(' ') else 1.35) * 0.55 ** s.count('\n')
    elif '\n' in s:
        n = s.count('\n')
        if n >= 3:
            value = 1.16
        elif n == 2:
            value = 1.36 if '：' not in s else 1.14
        else:
            value = 1.48
            if t.startswith((')', ']', "'", '"')):
                value = 1.02
    elif t.endswith(':') and '"' in t:
        value = 0.06
    elif t.endswith(':') and "'" in t:
        value = 0.43
    elif any(mark in t for mark in (':"', ':“', '："', '：“')):
        value = 0.73
    elif '：' in s:
        value = 1.76
    elif t == ':':
        value = 1.52 if s.startswith(' ') else 1.94
        if s == ':':
            # A bounded look behind, confined to the current document.
            context = ''.join(prefix.token_strings[-min(pos + 1, 49):-1])
            line = context.rsplit('\n', 1)[-1]
            identifier = re.search(r'[\w$]+$', context)
            before = context[:identifier.start()] if identifier else context
            key = bool(identifier) and before.rstrip().endswith(('{', ','))
            braces = context.count('{') > context.count('}')
            indent = line.startswith((' ', '\t'))
            if key and (braces or indent):
                value = 0.30 if braces and indent else 0.8
            elif braces:
                value = 1.4
            elif prefix.token_strings[-2].strip().isdigit():
                value = 2.15
            elif re.search(r'\.[A-Za-z]{1,5}$', context):
                value = 2.34
    elif t.startswith((')', ']', '}')) and t.endswith(':'):
        value = 1.85
    elif '*' in t or '?' in t or '#' in t or '=' in t:
        value = 1.25
    else:
        value = 1.5
    return carry, value

"""A signed spelling detector, strongest on RAY versus REAR/RARE.

Bare 'ray' and a split r + ay are strongly negative; rear/rare and split
r + ar are positive. Related vowel/glide spellings get weaker responses.
Token boundaries matter: a complete familiar word is not treated like its
short spelling fragments. Accents are folded, and Japanese 'rei' is recognized
by transliteration. This deliberately leaves most lexical and byte-fragment
exceptions unexplained rather than memorizing token identities.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()


def fold(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if unicodedata.category(c) != 'Mn')


def response(previous, token):
    s, p = fold(token).strip(), fold(previous)
    if s == 'ray':
        return -6.1
    if s == '-ray':
        return -1.3 if p.strip().endswith('x') else -5.5
    if s.startswith('rays'):
        return -1.6
    if re.fullmatch(r'[bcft]ray', s):
        return -1.0
    if s in ('rei', 'rey'):
        return -1.6
    if s == 'rai' or (not token[:1].isspace() and s in ('rail', 'rain')):
        return -1.2
    if s.startswith('raj'):
        return -1.8
    if s.startswith('relay'):
        return -1.2
    if s.startswith('rearr'):
        return 0.7
    if s.startswith('rear'):
        return 2.7
    if s in ('rare', 'rar'):
        return 1.3
    if not token.isascii() and anyascii(token).lower().strip() == 'rei':
        return -5.0

    # A continuation without leading whitespace can complete a split spelling.
    if token and not token[0].isspace():
        if p.endswith('r'):
            if s.startswith('ear'):
                return 6.8
            if s.startswith(('ar', 'air')):
                return 1.4 if p.endswith('tr') else 0.65
            if s == 'ay':
                return -5.7
            if s.startswith('ay'):
                return -1.5
            if s.startswith(('oy', 'oi')):
                return -0.9
            if s.startswith(('aj', 'ai')):
                return -0.5
            if s.startswith('aff'):
                return -1.0
            if s == 'af':
                return -2.5
        if p.endswith('rel') and s == 'ay':
            return -3.7
        if p.endswith('re'):
            if s in ('y', 'j'):
                return -2.9
            if s.startswith(('y', 'j')):
                return -0.3
            if s == 'ar':
                return 4.9
        if p.endswith('ra') and s.startswith(('y', 'j')):
            return -1.0
        if p.endswith(('ra', 're')) and s.startswith('i'):
            return -0.25
        if p.endswith('ro') and s.startswith('y'):
            return -1.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = response(old, token)
    if first and value == 0.0 and token.lstrip()[:1].isupper():
        value = 0.15
    return (doc, token), value

programs.haiku:
"""Layer 1, MLP down-projection, component 1969: a "ray"-sound detector.

What it responds to, in plain terms:
- Strongly negative on the word "ray" itself (Ray, ray, rays, -ray).
- Negative, less strongly, on other words and names that sound like "ray":
  Rey, Raj, Raid, Raf, Rai, Rei (and the Japanese レイ and Chinese 雷 for "rei").
- Negative when the same sound is split across two tokens: a piece ending in
  "r" followed by a piece such as "ay", "ai", "ey", "aj", "ei" (e.g. "R" + "ay").
- Mildly positive on "rear" and "rare", the words that sound like "rear" /
  "rare" (the vowel after r is "ea"/"ar", not "ay").
- Near zero everywhere else.

The program looks only at the current token and the one before it (in the same
document), so it is a lookup on spelling, with no state carried between tokens.
Values are typical activations read off a sample of training text.
"""

READS = ()

# The word "ray" and its spelling variants: strongly negative.
RAY_WORDS = {"ray", "rays"}
# Words and names that sound like "ray": moderately negative.
RAY_SOUND = {"rey", "reyn", "raj", "raf", "raid", "raids", "rai", "rei", "レイ", "雷"}
# Words that sound like "rear" / "rare": positive.
REAR_RARE = {"rear", "rearr"}
RARE = {"rare"}
# Second halves of a split "ray" sound: negative after a piece ending in "r".
RAY_PIECES = {"ay", "ays", "aya", "aj", "ey", "af", "ai", "ei", "oy"}


def _norm(token):
    return token.strip().lower().strip("-")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _norm(token)
    if word in RAY_WORDS:
        return carry, -5.0
    if word in RAY_SOUND:
        return carry, -1.6
    if word in REAR_RARE:
        return carry, 2.0
    if word in RARE:
        return carry, 1.2
    # Split "ray": the previous piece ends in "r" (same document), this piece
    # continues the word with no leading space.
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = _norm(prefix.token_strings[-2])
        if (
            not token.startswith(" ")
            and token.strip().lower() in RAY_PIECES
            and previous.endswith("r")
        ):
            return carry, -2.5
    return carry, 0.0

programs.sol:
"""Approximate the component's lexical core: ever/very-like spellings.

Ever and forever are strongest; very, never and yet are weaker. Modal
auxiliaries strengthen never; an -est ending or most/least strengthens ever.
A preceding you strengthens very; case and spacing adjust the ever response.
Short ev/ver fragments and poetic 'er also respond. A small spelling buffer
recognizes e+ver and ev+r/er across tokens (including Cyrillic counterparts).
Av fragments and a pair of middle dots are negative. Other text gets zero.
This leaves much of the component's rarer contextual behavior unmodeled.
"""
import re

READS = ()
MODALS = {'will', 'would', 'shall', 'should', 'can', 'could', 'may',
          'might', 'must', "'ll", '’ll', "'d", '’d'}
CYRILLIC = str.maketrans({'е': 'e', 'в': 'v', 'р': 'r'})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    spaced = bool(token and token[0].isspace())
    p = previous.strip().lower()
    value = 0.0
    if word == 'ever':
        value = 5.4 if token.strip()[0].isupper() else (3.7 if spaced else 2.0)
        if p.endswith('est') or p in {'most', 'least'}:
            value += 2.2
    elif word in ('forever', '-ever'):
        value = 3.6 if word == 'forever' else 4.5
    elif word == 'very':
        value = 1.1 + (1.5 if p == 'you' else 0.0)
    elif word == 'never':
        value = 0.34 + (0.6 if p in MODALS else 0.0)
    elif word == 'yet':
        value = 0.6 if spaced else 0.9
    elif re.fullmatch('[flrs]ever', word):
        value = 2.0
    elif word == "'er":
        value = 3.8
    elif word in ('ev', 'eve'):
        value = 0.8
    elif word.translate(CYRILLIC).startswith('ver') and len(word) <= 4:
        value = 0.2
    elif word in ('av', "'av"):
        value = -0.9 if spaced else -0.3
    elif word == '··':
        value = -1.6
    if not spaced and word.isalpha() and len(word) <= 5:
        a, b = tail.lower().translate(CYRILLIC), word.translate(CYRILLIC)
        if a.endswith('e') and b.startswith('ver'):
            value += 1.35 + (0.75 if len(p) <= 2 else 0.0)
            if a.endswith('fore'):
                value += 3.2
        if a.endswith('ev') and b.startswith(('r', 'er')):
            value += 1.0 + (2.7 if p.translate(CYRILLIC) == 'v' else 0.0)
    ending = re.search(r'[^\W\d_]+$', tail + token)
    tail = ending[0][-24:] if ending else ''
    return (doc, token, tail), value

programs.haiku:
"""Layer 1 MLP down_proj component 1970: a word-token detector for "ever".

It writes a large positive value when the current token is the word "ever"
(or a word ending in it that is a single token: "forever", "fever", "lever",
"sever"), a smaller positive value for the emphasis words "very", "yet" and
"never", and a small positive value for fragments of "ever" ("ev", "ver",
"vers"). It writes a negative value on "av" (a fragment of "avonoids" and
similar words) and on the "on" that follows it. Every other token gives 0.
Words like "however", "whatever" and "clever" are separate tokens here and
stay at 0, as they do in the data.
"""

READS = ()

# Typical activation of this component on each word token (from sampled text).
EVER_WORDS = {"ever": 3.7, "forever": 4.2, "fever": 2.2, "lever": 1.1, "sever": 2.0}
EMPHASIS = {"very": 1.2, "yet": 0.6, "never": 0.5}
EVER_FRAGMENTS = {"ev": 0.6, "ver": 0.3, "vers": 0.6}
AV_FRAGMENTS = {"av": -0.6, "ave": -0.4}
ON_AFTER_AV = -3.0  # the "on" in "av|on|oids" (Flavonoids and the like)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    for table in (EVER_WORDS, EMPHASIS, EVER_FRAGMENTS, AV_FRAGMENTS):
        if word in table:
            value = table[word]
    if word == "on" and len(prefix.token_strings) > 1:
        same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_doc and prefix.token_strings[-2].strip().lower().endswith("av"):
            value = ON_AFTER_AV
    return carry, float(value)

programs.sol:
"""Sparse lexical rules for selected Chinese and Japanese expressions.

Chinese action-progression words (continue, directly, again, formally), opening
verbs, and selected manner/extent modifiers give negative values. Some compounds
are stronger when completed across a token boundary. Selected ordinal completions
are negative too. Japanese 大-prefixed evaluations, どう-/まさか formulas, and
all/order/freshness expressions give positive values; repetition is negative.
Selected Japanese verb-ending fragments have small default responses.

This is deliberately a partial lexical account, not a general semantic classifier.
Recent UTF-8 bytes recognize split words/characters; documents reset the state.
"""
import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_CONVERTER = OpenCC('t2s')


@lru_cache(maxsize=32768)
def simplified(text):
    return _CONVERTER.convert(text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    joined = before + raw
    text = joined.decode('utf-8', errors='ignore')
    token = prefix.token_strings[-1]
    word = simplified(token)
    ending = simplified(text[-5:])
    value = 0.0

    # The strongest family: Chinese action-progression modifiers.
    if word.endswith(('继续', '直接')):
        value = -3.1
    elif word.endswith(('进一步', '再次')):
        value = -2.2
    elif word.endswith('正式'):
        value = -2.1
    elif word in {
        '再度', '初步', '独立', '独自', '真正', '真正的', '整个', '彻底'
    }:
        value = -1.1
    elif word in {'立即', '立刻', '即将', '单独', '一同', '一起', '亲自', '尽快'}:
        value = -0.65
    elif word in {'正面', '屡次'}:
        value = -1.6
    elif word == '一步':
        value = -0.9
    elif word in {'首次', '初次'}:
        value = -1.1
    elif word in {'全部', '完整', '分别', '重新', '主动'}:
        value = -0.35

    # Opening, including a verb and its directional complement split apart.
    elif word == '打开':
        value = -2.0
    elif word in {'开启', '开了', '不开'}:
        value = -0.9
    elif word in {'开', '敞', '启'}:
        value = -0.4

    # Strong compound completions when not already contained in this token.
    if ending.endswith('继续') and '继续' not in word:
        value = -3.7
    elif ending.endswith('直接') and '直接' not in word:
        value = -4.5
    elif ending.endswith('正式') and '正式' not in word:
        value = -5.0
    elif ending.endswith('打开') and word != '打开':
        value = -2.7
    elif ending.endswith('不忍') and word == '忍':
        value = -1.7
    elif word == '儿' and ending.endswith(('块儿', '真儿')):
        value = -1.5

    # Chinese ordinal repetitions and hundreds in chapter/section numbers.
    numerals = '零〇一二三四五六七八九十百千万两0-9'
    if re.search('第[' + numerals + ']+次$', ending):
        value = -1.1
    elif word in {'百', '千', '万'} and re.search('第[' + numerals + ']+$', ending):
        value = -1.1

    # Japanese evaluative expressions: all right, difficult, and much loved.
    if text.endswith('大丈夫'):
        value = 4.7
    elif text.endswith('大変'):
        value = 2.7
    elif text.endswith('大好き'):
        value = 2.1
    # Repetition: again, in kanji and phonetic spellings.
    elif text.endswith('再び'):
        value = -4.1
    elif text.endswith('ふたたび'):
        value = -1.8
    # Why/how, please, and the incredulous 'surely not'.
    elif text.endswith('どうして'):
        value = 3.7
    elif text.endswith(('どうか', 'どうぞ')):
        value = 2.7
    elif text.endswith('まさか'):
        value = 1.6
    # All, order/turn, and the 'freshly done' -たて spelling.
    elif text.endswith('全て'):
        value = 3.5
    elif text.endswith('順番'):
        value = 1.3
    elif token == 'て' and text.endswith('たて'):
        value = 1.9
    elif token == 'び':
        value = -0.5
    elif token in {'て', 'して', 'って'}:
        value = 0.3

    # An incomplete new character must not repeat the preceding word's response.
    if text == before.decode('utf-8', errors='ignore'):
        value = 0.0
    return (doc, joined[-48:]), value

"""A lexical mother / mum / mu detector, including spelling fragments.

Maternal words in several languages produce positive pulses. So do pieces
completing mother-like spellings, even in unrelated words such as 'moth'.
Some contrasting m/t spellings in Arabic, Greek and Cyrillic produce negative
pulses. Magnitudes are approximate training averages, not semantic strengths.
A short text tail handles split words; UTF-8 decoding handles split characters.
"""
import codecs
import re

READS = ()

# Arabic forms containing mim with ta or ayn (mt, tm, m-ayn).
ARABIC_FORMS = {'مع': -2.6, 'تم': -3.4, 'مت': -2.4,
                'يتم': -3.4, 'المت': -1.3}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their'}


def activation(token, previous, tail, split):
    if not token:
        return 0.0
    s = token.strip()
    word = s.lower()
    before = tail.lower()
    joined = before + token.lower()
    prev = previous.strip().lower()

    # The mother character, including non-family compounds such as vowels.
    if '母' in s:
        if s == '母':
            return 9.0 if split else 6.9
        return 3.0
    if s in ('妈妈', '媽媽', '爸爸妈妈', '爸爸媽媽'):
        return 2.0
    if any(c in s for c in '妈媽'):
        return 1.0
    if s == 'ママ':
        return 2.4 if before.endswith('シン') else 0.4
    if s == '모':
        return 3.6 if token[0].isspace() else 5.1

    if word == 'mother':
        return 3.1 if token[0].isspace() else 4.0
    if word == 'mothers':
        return 2.4
    if word in ('mom', 'moms'):
        return 2.2 if word == 'mom' else 1.6
    if word in ('mum', 'mums'):
        return 4.7
    if word == 'parents':
        return 1.7 if prev in POSSESSIVES else 0.7
    if word in ('madre', 'mère', 'mutter', 'mütter'):
        return 3.4
    if 'мам' in word:
        return 1.0
    if prev.endswith('мам') and word in ('а', 'ы', 'е', 'ой'):
        return 1.7
    if word == 'of' and prev in ('mother', 'mothers'):
        return 2.5

    if not token[0].isspace():
        # French mère, German Mutter/muth, English mother/mum fragments.
        if word == 'ère' and before.endswith('m'):
            return 4.4 if prev in ('m', '-m') else 0.8
        if before.endswith('m'):
            if word in ('utter', 'umm', 'ummy'):
                return 6.3
            if word == 'uth':
                return 4.9
            if word == 'ums':
                return 7.0
            if word in ('other', 'oth', 'oths'):
                return 5.2
            if word.startswith('ith'):
                return 1.9
            if word in ('om', 'um', 'ud'):
                return 3.0 if s.isupper() else 2.5
            if word in ('u', 'ü', 'ú'):
                return 0.5
        if word in ('th', 't', 'ter') and re.search(r'm[üú]$', before):
            return 4.9
        if word == 'mut' and prev in ('ver', 'er', 'un'):
            return 5.8
        if word == 'ut' and prev in ('verm', 'erm'):
            return 5.5
        if word in ('ths', 'th') and before.endswith('mo'):
            return 2.9
        if word == 'tern' and prev == 'el':  # German Eltern: parents
            return 7.7

    if word in ('moth', 'moths'):
        return 2.3
    if s in ('Mut', 'MUT'):
        return 0.5

    # Contrasting spelling neighbours, not translations of mother.
    if word in ARABIC_FORMS:
        if before.endswith('م') and word.startswith('ت'):
            return -7.0
        return ARABIC_FORMS[word]
    if not token[0].isspace():
        if before.endswith('م') and word.startswith(('ت', 'ط', 'ع', 'م')):
            return -1.3
        if before.endswith('ت') and word.startswith('م'):
            return -1.4
        if before.endswith('مت') and word and word[0].isalpha():
            return -1.4
        if re.search(r'μ[εέ]τ$', joined):
            return -8.3
        if re.search(r'μ[εέ]τ$', before) and word in ('α', 'ά'):
            return -7.6
        if re.search(r'м[еє]ж$', joined):
            return -5.5
        if joined.endswith('матем'):
            return -6.0
        if joined.endswith('mathem'):
            return -1.7
        if joined.endswith('metam'):
            return -3.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        carry = (doc, '', '', decoder)
    _, previous, tail, decoder = carry
    split = bool(decoder.getstate()[0])
    token = decoder.decode(prefix.token_bytes[-1])
    value = activation(token, previous, tail, split)
    return (doc, token, (tail + token)[-24:], decoder), value

programs.haiku:
"""layers.1.mlp.down_proj:1973 — the "that/since/because" clause-opener.

The component fires on the word that opens a clause stating a fact, reason or claim:
  * "that" after a word that takes a that-clause: "the fact that" (strongest), "consider
    that", "note that", "it is that", "showed that". A relative "that" after a concrete
    noun ("one that", "a system that") stays near zero.
  * reason conjunctions: "since" at the start of a clause ("..., since x"), "because",
    and a few foreign ones (que, что, как, 因为).
  * "which"/"where" after a preposition ("in which", "with which").
  * "fact" in "the fact ...", and the comma in "Wait, ..." / "Remember, ...".
  * "since" as a time word ("has since", "ever since", "years since") is negative.

Everything else predicts 0. Values are rough mean activations, fitted by hand on
training rows; they are not a learned model. The program is causal: it reads only the
current token and the one before it (and the document id, to reset at a new document).
"""

READS = ()

# After these words, "that" opens a clause that states a fact, reason or claim.
THAT_AFTER = {
    "fact": 5.0, "account": 4.0, "consider": 4.5, "considering": 4.5, "recall": 4.5,
    "remember": 4.0, "notice": 3.5, "given": 3.7, "except": 3.5, "sense": 4.0,
    "note": 2.7, "noting": 2.8, "noted": 1.6, "observe": 2.6, "understanding": 2.7,
    "is": 2.7, "was": 2.0, "in": 2.4, "means": 1.5, "mean": 1.0, "know": 1.3,
    "found": 1.3, "showed": 1.3, "shows": 1.0, "show": 0.9, "states": 1.4,
    "suggest": 0.9, "say": 1.0, "said": 0.9, "see": 1.2, "think": 0.5,
    "understand": 2.0, "realize": 1.1, "demonstrated": 1.2, "revealed": 1.3,
    "indicate": 1.1, "requires": 1.6, "extent": 2.5, "event": 2.2, "true": 2.2,
    "possibility": 1.9, "idea": 1.7, "condition": 1.3, "belief": 1.2, "meaning": 1.8,
    "so": 0.5, "such": 0.9,
}

# After these, "that" is a relative pronoun about a concrete thing: silent.
RELATIVE_AFTER = {
    "one", "thing", "system", "device", "file", "program", "code", "function",
    "company", "something", "those", "numbers", "elements", "vertices",
    "information", "product", "building", "all", "of", "for", "with", "to", "at",
}

# Words after which a new clause begins (so "since" here starts a reason clause).
CLAUSE_START = set(".,;:!?()\"\n") | {"", "but", "and", "so", "is", "or"}

# Words that cue a time sense of "since" ("has since", "ever since", "years since").
TIME_CUES = {
    "has", "have", "had", "ever", "years", "year", "time", "almost", "been",
    "months", "days", "weeks", "ago", "held", "working", "living", "long", "once",
    "decades", "since",
}

# Reason conjunctions in other languages, and their rough strength.
FOREIGN = {"que": 0.8, "что": 1.0, "как": 0.8, "因为": 1.5, "da": 0.5, "car": 0.5, "daß": 1.0}

WHICH_PREP = {"in", "with", "by", "of", "on", "at", "for", "to", "from"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip()
    prev = toks[-2].strip().lower() if len(toks) > 1 else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""  # a new document starts: nothing before it counts

    value = 0.0
    if toks[-1] == " that":
        if prev in THAT_AFTER:
            value = THAT_AFTER[prev]
        elif prev in RELATIVE_AFTER:
            value = 0.0
        else:
            value = 0.3
    elif cur.lower() == "because":
        value = 1.8
    elif cur.lower() == "since":
        if prev in CLAUSE_START or prev.endswith((")", ",", ".", ":")):
            value = 3.5
        elif prev in TIME_CUES:
            value = -1.0
        else:
            value = 1.0
    elif toks[-1] == " fact" and prev == "the":
        value = 3.5
    elif cur in ("which", "where"):
        value = 1.0 if prev in WHICH_PREP else 0.3
    elif cur in ("though", "while", "until", "when", "how"):
        value = 0.3
    elif cur in FOREIGN:
        value = FOREIGN[cur]
    elif cur == "as":
        value = 0.1
    elif toks[-1] == "," and prev in ("wait", "remember", "no", "hmm", "note"):
        value = 1.3
    return carry, float(value)

programs.sol:
"""A sparse detector of damaged or explicitly escaped character encodings.

Recognize PDF private-use fi/fl/ft glyphs, printed hexadecimal escapes,
numeric HTML entities, and one or two rounds of UTF-8 mojibake. Signs and
sizes differ between these artifacts; the default prediction is zero.
Most ordinary-word responses are deliberately left unmodeled.
"""
import re
import unicodedata as ud

READS = ()
# Glyph meanings inferred from spellings in the PDF-extracted training text.
PDF_LIGATURES = {
    '\ue103': 3.6,   # fi
    '\ue104': 2.05,  # fl
    '\ue09d': 1.3,   # ft
}
QUOTATION_BYTE_ENDINGS = {
    b'c': -0.47,  # UTF-8 left double quotation mark: ...\\x9c
    b'd': -0.18,  # right double quotation mark: ...\\x9d
    b'9': 0.36,   # right single quotation mark: ...\\x99
}
ENTITY = re.compile(rb'&#([0-9]{1,7});$')
DOUBLE = re.compile(r'Ã(?:\x83|ƒ) ?Â?([\x80-\xbf])$')

def mojibake(text):
    if DOUBLE.search(text):
        return 2.8
    # Displayed UTF-8 lead bytes in the code pages considered below.
    if text[-2] not in 'ÃÄÅГĹ' and text[-3:-2] not in 'ïпď':
        return 0.0
    for encoding in ('latin1', 'cp1252', 'cp1251', 'cp1250'):
        for length in (2, 3):
            try:
                repaired = text[-length:].encode(encoding).decode('utf-8')
            except UnicodeError:
                continue
            if len(repaired) != 1:
                continue
            if ud.name(repaired, '').startswith('LATIN SMALL LIGATURE'):
                return 2.4
            lead = text[-2]
            if lead not in 'ÃÄÅГĹ':
                continue
            if lead == 'Г' and not (len(text) > 2 and text[-3].isascii()
                                    and text[-3].isalpha()):
                continue
            if repaired == 'Ã':
                return -0.6
            if repaired.islower() or ud.category(repaired) == 'Sm':
                return 2.4 if lead == 'Г' else 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', ())
    _, before, history = carry
    b = prefix.token_bytes[-1]
    tail = (before + b)[-64:]
    value = 0.0

    # Printed byte escapes: form feed, UTF-8 punctuation, and PDF ligatures.
    if b == b'c' and before.endswith(b'\\x0'):
        value = -1.8
    elif b == b'b' and before.endswith(b'\\x1'):
        value = -0.6
    elif b == b'2' and before.endswith(b'\\xe'):
        value = 0.6 if history[-1:] == (b'xe',) else -0.13
    elif b == b'8' and before.endswith(b'\\x'):
        value = -0.5 if history[-3:-2] == (b'xe',) else 0.0
        if before.endswith(b'\\xac\\x'):
            value = -1.1
    elif b == b'ac' and before.endswith(b'\\x'):
        value = -1.8
    elif b == b'ef' and before.endswith(b'\\x'):
        value = -1.0
    elif b == b'\\xa':
        value = -0.65 if before.endswith(b'\\x80') else -0.1
    elif b == b'0' and before.endswith(b'\\xa'):
        value = -0.35
    elif b == b'1' and before.endswith(b'\\x8') and b'\\xac' in before[-12:]:
        value = 0.4
    elif b == b'0' and before.endswith(b'\\x8'):
        value = 0.16
    elif b == b'0' and before.endswith(b'\\x'):
        value = 0.19
    elif b == b'9' and before.endswith(b'\\x'):
        value = 0.2
    elif before.endswith(b'\\x9'):
        value = QUOTATION_BYTE_ENDINGS.get(b, value)

    # Printed named delimiters and non-ASCII Unicode escapes.
    if b in {b'open', b'close'} and before.endswith(b'\\<'):
        value = 0.55
    elif b == b'>' and before.endswith((b'\\<open', b'\\<close')):
        value = 0.4
