from functools import lru_cache
import re
import unicodedata
from anyascii import anyascii

# Familiar Greek combining forms, including common spelling variants.
ROOTS = (
    'graph', 'graf', 'log', 'nom', 'tom', 'soph', 'sof', 'metr', 'met',
    'phys', 'fys', 'fiz', 'chem', 'chim', 'dynam', 'dinam', 'therm', 'term',
    'morph', 'morf', 'phon', 'fon', 'phot', 'fot', 'chrom', 'therap',
    'trop', 'troph', 'trof', 'polem', 'plast', 'plas', 'plasm',
    'ops', 'op', 'opt', 'optr', 'sthes', 'stes', 'thes', 'potam', 'botan',
    'typ', 'path', 'pat', 'phag', 'tax', 'crat', 'krat', 'phor', 'for',
    'phantas', 'fantas', 'poes', 'poet', 'energ', 'genet', 'gon',
    'polit', 'crit', 'gnost', 'stat', 'stas', 'echo', 'hypnot',
    'histor', 'istor', 'theor', 'teor', 'the', 'scop', 'iatr', 'top',
    'phores', 'eurys', 'thrips', 'trips',
)
I_NOUNS = frozenset(('ia', 'ii', 'io', 'iya', 'ya'))
FOREIGN_IC = frozenset((
    'ik', 'ick', 'ique', 'iques', 'isk', 'iska', 'iske', 'iek', 'iker',
    'isch', 'ische', 'ischen', 'ischer', 'isches',
))
SCIENTIFIC_Y = frozenset((
    'omy', 'nomy', 'tomy', 'metry', 'graphy', 'logy', 'ology', 'scopy',
    'ropy', 'phagy', 'agy', 'iatry', 'plasty',
))
OTHER_ENDINGS = frozenset((
    'ian', 'ean', 'ist', 'ista', 'ists', 'istic', 'istica', 'istik', 'ism',
    'im', 'in', 'is', 'em', 'm', 'ms', 'se', 'ry', 'rie', 'yped', 'typed',
    'ka', 'ki', 'ku', 'ika', 'iki', 'iku', 'a', 'e', 'i', 'o', 'any', 'my',
))
ROOT_ENDINGS = (
    'ia', 'ie', 'y', 'ies', 'ic', 'ical', 'ics', 'ically', 'ist', 'ism',
    'a', 'i', 'e', 'o', 'ii', 'ya', 'ka', 'ki', 'ku', 'ika', 'is', 'm',
    'ms', 'ed', 's', 'en', 'ico', 'ica', 'ici', 'icas', 'icos',
    'ische', 'ischen', 'ik', 'ique', 'iques', 'iske', 'iska',
)
LATIN_ENDINGS = frozenset(('al', 'ial', 'rial', 'ion', 'ile', 'il', 'ate'))

@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()

@lru_cache(maxsize=65536)
def root_at_end(word):
    return word.endswith(ROOTS) or word.endswith(tuple(r + 'i' for r in ROOTS))

@lru_cache(maxsize=65536)
def formed_from_root(word):
    return root_at_end(word) or any(
        word.endswith(e) and root_at_end(word[:-len(e)]) for e in ROOT_ENDINGS
    )

def word_tail(word, token):
    if token.isalpha():
        return (word + token)[-64:]
    match = re.search(r'[^\W\d_]+$', token)
    return match.group() if match else ''

READS = ()

# (ordinary ending, adjustment beside a classical stem)
ENDING_WEIGHTS = {
    'ie': (0.183, 2.4069),
    'ia': (0.1242, 1.1697),
    'y': (0.0334, 0.8467),
    'ic': (0.1727, 0.4517),
    'ik_ique': (0.2201, 0.8948),
    'scientific_y': (0.8572, -0.6003),
    'other': (0.0022, 0.3366),
    'latin': (-0.0102, -0.4335),
    'greek_letters': (0.0341, 0.0353),
}

BIAS = 0.0025
FIRST = -0.0642
DOT_LEADER = 1.3456
OPENING_DOCSTRING = 0.6507
OF_DISCIPLINE = 0.367
SIS_NOUN = 0.634
SM_NOUN = 0.1913


def activation(word, token, position):
    value = BIAS
    if token and set(token) == {'·'} and len(token) >= 2:
        value += DOT_LEADER
    if position == 0:
        value += FIRST
        if token.startswith(('"""', "'''")):
            value += OPENING_DOCSTRING
        return value
    prev, tok = roman(word), roman(token)
    if tok == ' of' and prev.endswith((
            'ogy', 'ophy', 'istry', 'theory', 'omy', 'metry', 'physics', 'rhetoric')):
        value += OF_DISCIPLINE
    if not token.isalpha() or not word:
        return value
    if len(token) <= 3 and unicodedata.name(token[0], '').startswith('GREEK'):
        family = 'greek_letters'
    elif tok == 'ie':
        family = 'ie'
    elif tok in I_NOUNS:
        family = 'ia'
    elif tok in ('y', 'ies'):
        family = 'y'
    elif tok in FOREIGN_IC:
        family = 'ik_ique'
    elif tok in SCIENTIFIC_Y:
        family = 'scientific_y'
    elif tok in ('ic', 'ical', 'ically', 'ics', 'ico', 'ica', 'ici',
                 'icos', 'icas', 'iche', 'ichi', 'ice', 'atic', 'etic',
                 'otic', 'mic', 'itic'):
        family = 'ic'
    elif tok in OTHER_ENDINGS:
        family = 'other'
    elif tok in LATIN_ENDINGS:
        family = 'latin'
    else:
        return value
    ordinary, classical = ENDING_WEIGHTS[family]
    value += ordinary
    if root_at_end(prev) or formed_from_root(prev + tok):
        value += classical
    if tok == 'is' and prev.endswith('s'):
        value += SIS_NOUN
    if tok in ('m', 'ms') and prev.endswith('s'):
        value += SM_NOUN
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        word, position = '', 0
    else:
        _, word, position = carry
    value = activation(word, token, position)
    return (document, word_tail(word, token), position + 1), float(value)

