import re

READS = ()


def unfinished(text):
    """A substantial prose fragment without a sentence-ending mark."""
    text = text.strip()
    return (len(text) > 120 and len(text.split()) >= 15
            and bool(re.search(r'[A-Za-z,]$', text))
            and '\n' not in text and '`' not in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
