"""Approximate this component with spelling and surface-syntax rules.

Document starts have larger predictions: scalar type names and declarations
are negative, while short s-vowel-l spellings are positive. Common-word
frequency and dictionary noun/verb categories provide a coarse fallback.
Inside documents, recognize chat markers, template openers, a few English
phrases, and code punctuation. Most other tokens receive a small value.
This leaves much token-specific variation unexplained. State is just the
previous token and the last 200 characters of the current line, reset per doc.
"""

from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()

SCALAR_TYPES = {
    'int', 'uint', 'integer', 'char', 'string', 'str', 'float', 'double',
    'bool', 'boolean', 'byte', 'short', 'long', 'void',
}
DECLARATIONS = {'def', 'function', 'class', 'struct', 'interface'}
QUESTION_WORDS = {'when', 'where', 'what', 'why', 'how', 'which', 'who'}
NULL_OR_BOOLEAN = {'null', 'nil', 'none', 'undefined', 'true', 'false'}
CHAT_MARKERS = {
    '<|im_start|>': -0.088,
    '<|im_end|>': -0.024,
    '</tool_call>': 0.081,
    '<think>': 0.066,
    '<tool_response>': 0.034,
}


@lru_cache(maxsize=32768)
def initial_value(token):
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    # A spelling rule for short syllabic openings, not a claim about meaning.
    if (3 <= len(word) <= 4 and word.isalpha()
            and lower[0] == 's' and lower[1] in 'aeiou' and lower[2] == 'l'):
        if word[0] == 'S':
            return 0.35 if spaced else 0.65
        return 0.25
    if word in SCALAR_TYPES:
        return -1.5 if token == word else -0.25 if spaced else -0.65
    if word in DECLARATIONS or word == 'type':
        return -0.65
    if lower == 'user':
        return -1.1 if token == word else -0.6
    if word in {'import', '#include'}:
        return -0.35 if token == word else 0.04
    if word.startswith('//'):
        return -1.8 if '\n' in token else -0.45
    if lower in QUESTION_WORDS:
        return -0.12 if spaced else -0.45
    if lower in {'if', 'unless'}:
        return -0.28 if spaced else -0.45
    if lower in {'i', 'my', 'mine'}:
        return 0.4
    pos = wordnet.parts_of_speech(lower) if word.isalpha() else set()
    if word.isalpha() and zipf_frequency(lower, 'en') > 5.5:
        if len(word) == 1:
            return 0.07
        if lower in {'the', 'an'}:
            return -0.17 if spaced else -0.27
        return -0.02 if 'verb' in pos else -0.12
    if '=' in token:
        return -0.22
    if len(word) > 3 and word.islower():
        return -0.14 if 'noun' in pos else 0.01
    return 0.04


def inside_value(token, previous, line):
    word = token.strip()
    prev = previous.strip()
    if token in CHAT_MARKERS:
        return CHAT_MARKERS[token]
    if word == '://':
        return 0.14
    if word == '.com':
        return -0.086
    if word in {'&&', '||'}:
        if prev.lower() in NULL_OR_BOOLEAN:
            return -0.15
        if prev.endswith((')', '"', "'")):
            return -0.11
        return -0.01 if token == '||' else -0.06
    if word in {'%', '%='} and previous.endswith('<'):
        return -0.45 if previous == '<' and word == '%=' else -0.29
    if word.lower() == 'echo':
        return -0.5 if prev.endswith('php') else -0.05
    if word == 'import':
        return -0.054 if token == word else 0.045
    if word == '`' or '\\"' in token:
        return -0.045
    if word == '-':
        return -0.014
    if '\x00' in token:
        return -0.14
    if word == '=':
        target = line.strip()
        if (target.isascii() and target.isidentifier()) or prev.startswith('_'):
            return 0.07
        if prev.startswith('.') or prev.endswith(']'):
            return -0.035
        return 0.01 if token.startswith(' ') else 0.0
    if word.lower() == 'only' and prev.lower() == 'not':
        return 0.145
    if word.lower() == 'to' and prev.lower() == 'as':
        return 0.11
    if ':' in token:
        return 0.02 if len(word) > 1 else 0.005
    if ';' in token:
        return 0.01
    if word.lower().endswith('ing') and len(word) > 5:
        return 0.008
    if len(word) > 2 and '>' in token:
        return 0.028
    return -0.0005


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, line = ('', '') if first else carry[1:]
    value = initial_value(token) if first else inside_value(token, previous, line)
    line = (line + token).rsplit('\n', 1)[-1][-200:]
    return (doc, token, line), value

