"""Layer-1 MLP down_proj, component 1980: a weak, diffuse contributor.

Its activation is almost always near zero (std 0.03) and has no clean concept behind it.
The only large values are (a) at the first token of a document, where the value depends
only on the token itself, and (b) a long tail of token-specific offsets. This program
captures the parts that can be stated in plain terms:

1. First token of a document that is a programming keyword (int, def, class, print,
   import, ...): strongly negative.
2. Otherwise, a handful of token families with a consistent small offset:
   - chat/markup tags and repeated-symbol runs (<|im_start|>, ··, `, ^^^^): negative
   - URL / module path pieces (://, _modules, .com after github): positive or negative
   - the assignment sign " =": slightly positive
   - a few word-like tokens (PASS, ||, shall, Download, &&): negative
Everything else predicts 0. It has no memory across positions beyond the document start.
"""

READS = ()

CODE_START = {"int", "user", "def", "function", "type", "class", "print", "const", "import",
              "var", "let", "return", "static", "if", "null", "new", "void", "struct",
              "include", "fn", "main", "package", "public", "private", "self", "async",
              "export", "from", "func"}
MARKUP = {"<|im_start|>", "<|im_end|>", "</tool_call>", "<think>", "</think>"}
REPEAT = {"··", "`", "^^^^", "^^^^^^^^"}
URL = {"://", ".com", "_modules", ".go", ".ts"}
WORDS = {"PASS", "||", "shall", "org", "Download", "&&", "Marshall", "@Override", "isk"}
ASSIGN = {"="}

# Mean activation of each family, measured on training rows (see the notes above).
VALUES = {
    "code_start": -0.7,
    "markup": -0.03,
    "repeat": -0.064,
    "url": 0.025,
    "assign": 0.016,
    "words": -0.09,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc_start = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        return None, (VALUES["code_start"] if word in CODE_START else 0.0)
    if token in MARKUP:
        return None, VALUES["markup"]
    if token in REPEAT:
        return None, VALUES["repeat"]
    if token in URL:
        return None, VALUES["url"]
    if token in ASSIGN or token == " =":
        return None, VALUES["assign"]
    if token in WORDS or word in WORDS:
        return None, VALUES["words"]
    return None, 0.0

programs.sol:
"""A token-boundary-sensitive spelling feature centered on B.

Abort- gives a large positive response; the place-name suffix -bury is negative.
Smaller rules recognize b plus short following syllables, including Cyrillic
spellings. Long tokens with the same initial letters are not interchangeable
with those syllable tokens. Unrecognized spellings get a near-zero baseline.
"""
from anyascii import anyascii
from functools import lru_cache
import regex

READS = ()


@lru_cache(maxsize=32768)
def latin(text):
    # Preserve Latin accents, which distinguish otherwise similar syllables.
    if regex.search(r'\p{Script=Cyrillic}', text):
        text = anyascii(text)
    return text.lower()


def response(previous, token, word):
    s, p = latin(token), latin(previous)
    if s.lstrip().startswith('abort'):
        if s.lstrip().startswith('abortions'):
            return 5.0
        return 7.1 if s.lstrip().startswith('abortion') else 8.7
    if s.startswith('bury'):
        return -4.4
    if s.strip() in ('brow', 'bow'):
        return -0.7
    if s.strip() == 'bent':
        return -0.8
    if not s or s[0].isspace():
        return 0.003
    if word.endswith('bor') and token.startswith('ь'):
        return 5.7
    if p.endswith('abort') and s == 'us':
        return 6.4
    if p.endswith('bar') and s in ('row', 'rows'):
        return -5.1
    if p.endswith(('bor', 'br')) and s == 'ator':
        return 2.7
    if not p.endswith('b'):
        return 0.003
    if s == 'osnov':
        return -5.8
    if previous.lower().endswith('об') and s == 'n':
        return -4.5
    if p.endswith('ab') and s in ('end', 'ends', 'ende'):
        return 5.1
    if s in ('ort', 'ord'):
        return 4.9
    if s in ('or', 'ore'):
        return 1.7
    if s in ('at', 'att', 'atic', 'ated', 'ating', 'atement'):
        return 2.5 if p.endswith('ab') else 0.5
    if s in ('ot', 'ots', 'otic'):
        return 4.1 if p.endswith('ab') else 2.1
    if s in ('ola', 'olas', 'od', 'ode', 'odes'):
        return 1.0
    if s == 'ary':
        return -4.1
    if s == 'own':
        return -5.4
    if s in ('ur', 'uri', 'ury', 'ure'):
        return -2.1
    if s in ('ow', 'ound', 'ounded', 'ower', 'ost'):
        return -1.4
    return 0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, word = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = response(previous, token, word)
    for ch in latin(token):
        word = (word + ch)[-16:] if ch.isalpha() else ''
    return (doc, token, word), value

"""A local spelling approximation, not a general semantic classifier.

Fuse/fusion-looking fragments, Chinese 融 compounds, melting characters,
and digits immediately adjoining F get positive values. Short fr- fragments
and certain F-following abbreviations get negative values. Prefixes such
as diff-, conf-, and inf- change the strength of a fuse-like continuation.
Most other activity is omitted. Only the previous token is remembered.
"""

READS = ()


def response(previous, token):
    s, prev = token.lower(), previous.lower()
    bare = s.lstrip()
    if '融' in token:
        return 7.796 if token == '融' else 3.8
    if token in ('溶', '熔'):
        return 4.3

    if prev.endswith('f') and s and not s[0].isspace():
        if s.isascii() and s.isdigit():
            return 1.7 if prev.strip() == 'f' else 1.1
        if s.startswith('us'):
            if prev.endswith('diff'):
                return 1.648
            if prev.endswith('conf'):
                return 2.4
            if prev.endswith('ref'):
                return 2.1
            if prev.endswith(('inf', 'suff')):
                return 7.071
            if prev.endswith(('def', 'prof', 'eff', 'perf', 'transf')):
                return 2.8
            if s == 'use':
                return 11.216
            if s.startswith(('used', 'uses', 'using')):
                return 8.0
            return 5.2 if s.startswith('usion') else 4.514
        if s.startswith('rozen'):
            return 0.0
        if s.startswith('mri'):
            return -3.485
        if s.startswith(('mt', 'ml')):
            return -2.5
        if s.startswith('r'):
            return -0.75
        if s.startswith(('om', 'on', 'or', 'op')):
            return -0.27

    if bare in ('fr', 'fro', 'fra', 'fri'):
        if bare == 'fra':
            return -2.18
        return -2.612 if bare == 'fr' and prev.endswith(('en', 'con')) else -0.515
    if prev.endswith('fr') and s and not s[0].isspace():
        return -0.33

    if bare.startswith('fus'):
        # A piece inside another word, e.g. con|fusion, is not a new root.
        if s == bare and prev and prev[-1].isalpha():
            return 0.0
        if bare.startswith('fused'):
            return 8.557
        if bare.startswith('fuse'):
            return 7.3
        return 5.0 if bare.startswith('fusion') else 2.7
    if bare == 'infused':
        return 5.475
    if bare == 'infusion':
        return 2.733
    if bare.startswith('financ'):
        return 2.8 if bare.startswith('financing') else 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(previous, token))
